-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0006 — Customer requests & demand
-- ============================================================================
-- Customers have no account. They may submit a request through an RPC that is
-- open to `anon`, which is the ONLY write path available to the public.
-- Reading requests back is restricted: they contain phone numbers.
-- ============================================================================

create table if not exists public.customer_requests (
  id                     uuid        primary key default gen_random_uuid(),
  request_number         text        unique not null,
  customer_name          text,
  customer_phone         text,
  product_id             uuid        references public.products(id),
  requested_product_name text        not null,
  quantity               int         not null default 1,
  message                text,
  photo_url              text,
  source                 public.request_source not null default 'WEBSITE',
  status                 public.request_status not null default 'NEW',
  -- demand analytics
  was_unavailable        boolean     not null default false,
  category_id            uuid        references public.categories(id),
  -- operational trail
  handled_by             uuid        references public.app_users(id),
  owner_note             text,
  status_history         jsonb       not null default '[]'::jsonb,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  constraint requests_qty_positive check (quantity > 0)
);

create index if not exists requests_status_idx   on public.customer_requests (status, created_at desc);
create index if not exists requests_product_idx  on public.customer_requests (product_id, created_at desc);
create index if not exists requests_phone_idx    on public.customer_requests (customer_phone);
create index if not exists requests_created_idx  on public.customer_requests (created_at desc);
create index if not exists requests_demand_idx   on public.customer_requests (requested_product_name, created_at desc);

drop trigger if exists trg_requests_touch on public.customer_requests;
create trigger trg_requests_touch before update on public.customer_requests
  for each row execute function public.fn_touch_updated_at();

-- Status transitions are appended to the row's own history so the funnel is
-- reconstructable without joining anything.
create or replace function public.fn_request_status_history()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.status is distinct from old.status then
    new.status_history := coalesce(old.status_history, '[]'::jsonb)
      || jsonb_build_object(
           'from', old.status, 'to', new.status,
           'at', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SSOF'),
           'by', auth.uid()
         );
    new.handled_by := coalesce(auth.uid(), new.handled_by);
  end if;
  return new;
end $$;

drop trigger if exists trg_requests_history on public.customer_requests;
create trigger trg_requests_history before update on public.customer_requests
  for each row execute function public.fn_request_status_history();

-- Rate limiting for the public (anon) request endpoint: a light guard so the
-- catalog cannot be spammed through the open RPC.
create table if not exists public.request_rate_limit (
  id          bigserial   primary key,
  phone_hash  text        not null,
  created_at  timestamptz not null default now()
);
create index if not exists request_rate_idx on public.request_rate_limit (phone_hash, created_at desc);

-- ---------------------------------------------------------------------------
-- Backup runs — surfaced to the Owner as a backup status card (spec §58)
-- ---------------------------------------------------------------------------
create table if not exists public.backup_runs (
  id            uuid        primary key default gen_random_uuid(),
  started_at    timestamptz not null default now(),
  finished_at   timestamptz,
  status        text        not null default 'RUNNING',   -- RUNNING | SUCCESS | FAILED
  backup_type   text        not null default 'WEEKLY_PG_DUMP',
  size_bytes    bigint,
  table_count   int,
  row_count     bigint,
  storage_files int,
  location      text,
  notes         text
);

create index if not exists backup_runs_idx on public.backup_runs (started_at desc);

-- ----------------------------------------------------------------------------
-- >>> 0007_security_helpers.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0007 — Security helper functions
-- ============================================================================
-- All SECURITY DEFINER with a pinned search_path. These are the primitives that
-- every RLS policy and every RPC guard is built from.
-- ============================================================================

create or replace function public.fn_current_user_row()
returns public.app_users
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select u.* from public.app_users u where u.id = auth.uid();
$$;

create or replace function public.fn_is_owner()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.app_users u
    where u.id = auth.uid() and u.role = 'OWNER' and u.active
  );
$$;

create or replace function public.fn_is_staff()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.app_users u
    where u.id = auth.uid() and u.role = 'STAFF' and u.active
  );
$$;

create or replace function public.fn_is_internal()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.app_users u
    where u.id = auth.uid() and u.role in ('OWNER','STAFF') and u.active
  );
$$;

create or replace function public.fn_current_supplier_id()
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select su.supplier_id
  from public.supplier_users su
  join public.app_users u on u.id = su.user_id
  where su.user_id = auth.uid()
    and su.status = 'ACTIVE'
    and u.active
  limit 1;
$$;

create or replace function public.fn_is_supplier()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.fn_current_supplier_id() is not null;
$$;

-- ---------------------------------------------------------------------------
-- Guards. Raised as SQLSTATE 42501 so the API layer can map them to HTTP 403
-- and the UI can render a friendly "not permitted" state.
-- ---------------------------------------------------------------------------
create or replace function public.fn_require_owner()
returns void
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.fn_is_owner() then
    raise exception 'OWNER_ONLY: this action is restricted to the shop owner' using errcode = '42501';
  end if;
end $$;

create or replace function public.fn_require_internal()
returns void
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.fn_is_internal() then
    raise exception 'INTERNAL_ONLY: this action is restricted to LuBella staff' using errcode = '42501';
  end if;
end $$;

create or replace function public.fn_require_open_period(p_date date)
returns void
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_month date := date_trunc('month', p_date)::date;
begin
  if exists (select 1 from public.period_closes pc
             where pc.period_month = v_month and pc.status = 'CLOSED') then
    raise exception 'PERIOD_CLOSED: % is closed. Post a controlled, audit-logged adjustment instead.',
      to_char(v_month, 'Mon YYYY') using errcode = '42501';
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Settings access
-- ---------------------------------------------------------------------------
create or replace function public.fn_setting(p_key text, p_default jsonb default null)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce((select s.value from public.settings s where s.key = p_key), p_default);
$$;

-- Safe for any audience: only rows explicitly flagged is_public can ever be
-- returned, so it cannot be used to read the Telegram bot token even though it
-- has the same shape as fn_setting().
create or replace function public.fn_public_setting(p_key text, p_default jsonb default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  -- plpgsql so the definer context cannot be inlined away (see 0008_views.sql).
  return coalesce((select s.value from public.settings s where s.key = p_key and s.is_public), p_default);
end $$;

-- Public settings only: used by the customer portal and by the message builders.
create or replace function public.fn_public_settings()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(jsonb_object_agg(s.key, s.value), '{}'::jsonb)
  from public.settings s where s.is_public;
$$;

-- ---------------------------------------------------------------------------
-- Order-message builder (spec §8, §10).
-- Runs on the server so the WhatsApp/Telegram number is never hard-coded in a
-- component, and so message text is consistent between web, bot and staff.
-- ---------------------------------------------------------------------------
create or replace function public.fn_build_order_message(
  p_items   jsonb,      -- [{"name":"Maybelline Lipstick","quantity":2,...}]
  p_total   numeric default null,
  p_customer text default null,
  p_phone    text default null,
  p_kind     text default 'ORDER'   -- ORDER | REQUEST
) returns text
language plpgsql
immutable
as $$
declare
  v_lines text[] := '{}';
  v_item  jsonb;
  v_msg   text;
begin
  if p_kind = 'REQUEST' then
    v_msg := 'Hello LuBella,' || E'\n\n' || 'I would like to request:' || E'\n\n';
  else
    v_msg := 'Hello LuBella,' || E'\n\n' || 'I would like to order:' || E'\n\n';
  end if;

  for v_item in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    v_lines := v_lines || format('Product: %s' || E'\n' || 'Quantity: %s',
      v_item ->> 'name', coalesce(v_item ->> 'quantity', '1'));
  end loop;

  v_msg := v_msg || array_to_string(v_lines, E'\n\n');

  if p_total is not null and p_total > 0 then
    v_msg := v_msg || E'\n\n' || '----------------' || E'\n' ||
             format('Estimated Total: %s Birr', to_char(p_total, 'FM999,999,999,990.00'));
  end if;

  if p_customer is not null then
    v_msg := v_msg || E'\n\n' || format('Customer: %s', p_customer);
  end if;
  if p_phone is not null then
    v_msg := v_msg || E'\n' || format('Phone: %s', p_phone);
  end if;

  if p_kind = 'REQUEST' then
    v_msg := v_msg || E'\n\n' || 'Please notify me when available.';
  else
    v_msg := v_msg || E'\n\n' || 'Please confirm availability and price.';
  end if;

  v_msg := v_msg || E'\n\n' || 'Thank you.';
  return v_msg;
end $$;

-- Build the deep links the customer portal opens. Uses only PUBLIC settings.
create or replace function public.fn_contact_links(p_message text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_wa    text := coalesce(public.fn_setting('whatsapp_number', 'null'::jsonb) #>> '{}', '');
  v_tg    text := coalesce(public.fn_setting('telegram_username', 'null'::jsonb) #>> '{}', '');
  v_tg_bot text := coalesce(public.fn_setting('telegram_bot_username', 'null'::jsonb) #>> '{}', '');
  v_wa_clean text;
begin
  v_wa_clean := regexp_replace(v_wa, '[^0-9]', '', 'g');
  return jsonb_build_object(
    'whatsapp_number', v_wa,
    'telegram_username', v_tg,
    'whatsapp_url', case when v_wa_clean = '' then null
                    else 'https://wa.me/' || v_wa_clean || '?text=' || public.fn_urlencode(p_message) end,
    'telegram_url', case when v_tg_bot <> '' then 'https://t.me/' || v_tg_bot || '?start=' || public.fn_urlencode(left(p_message, 64))
                    when v_tg <> '' then 'https://t.me/' || v_tg
                    else null end,
    'message', p_message
  );
end $$;

create or replace function public.fn_urlencode(p_text text)
returns text
language sql
immutable
as $$
  select string_agg(
    case
      when c ~ '[A-Za-z0-9_.~-]' then c
      when c = ' ' then '+'
      else '%' || upper(lpad(to_hex(ascii(c)), 2, '0'))
    end, '' order by ord)
  from (
    select substr(p_text, i, 1) as c, i as ord, ascii(substr(p_text, i, 1)) as ascii
    from generate_series(1, greatest(length(p_text), 0)) i
  ) chars;
$$;

-- ----------------------------------------------------------------------------
-- >>> 0008_views.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0008 — Curated views
-- ============================================================================
-- Two kinds of view, deliberately different:
--
--  1. COLUMN-CURATED views (security_invoker = false, i.e. definer).
--     Owned by the database owner, granted to a specific audience, and written
--     so that restricted columns simply DO NOT EXIST in the view. This is how
--     staff get real stock numbers without ever being able to reach cost, and
--     how a supplier gets their ledger without ever reaching LuBella's margin.
--
--  2. GUARDED views for owner-only financial reports.
--     These are also definer views, but every one of them carries an explicit
--     `where public.fn_is_owner()` predicate, so a staff or supplier token gets
--     zero rows even though the view name is guessable. Two independent layers
--     (grant + guard) plus the owner-only RLS on the base tables.
--
--     They are deliberately NOT security_invoker: an invoker view would force
--     us to grant staff EXECUTE on cost helpers such as fn_avg_unit_cost(),
--     and that grant would itself be the leak we are closing.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Availability is a first-class business rule, so it lives in one function.
--   out  : nothing sellable
--   low  : at or below the product's configured minimum
--   available
-- ---------------------------------------------------------------------------
create or replace function public.fn_availability(p_on_hand int, p_minimum int)
returns text
language sql
immutable
as $$
  select case
    when coalesce(p_on_hand, 0) <= 0 then 'OUT'
    when coalesce(p_on_hand, 0) <= greatest(coalesce(p_minimum, 0), 0) then 'LOW'
    else 'AVAILABLE'
  end;
$$;

create or replace function public.fn_expiry_status(p_expiry date, p_warn_days int)
returns text
language sql
immutable
as $$
  select case
    when p_expiry is null then 'NONE'
    when p_expiry < current_date then 'EXPIRED'
    when p_expiry <= current_date + make_interval(days => greatest(p_warn_days, 0)) then 'EXPIRING_SOON'
    else 'OK'
  end;
$$;

-- ---------------------------------------------------------------------------
-- IMPORTANT PostgreSQL behaviour this file depends on:
--   Inside a definer view (security_invoker = false), privileges on the
--   underlying TABLES are checked against the view owner, but EXECUTE on any
--   FUNCTION in the view is checked against the CALLER. A view that calls
--   fn_on_hand() therefore forces us to grant fn_on_hand to whoever may read
--   the view — which for the public catalog would leak exact stock quantities.
--
--   So every function used by a view is an audience-guarded wrapper that
--   returns only what that audience is entitled to. The dangerous primitives
--   (fn_on_hand, fn_avg_unit_cost, fn_setting) stay ungranted, and are reachable
--   only from inside SECURITY DEFINER code, where the current user IS the owner.
-- ---------------------------------------------------------------------------

-- Public: the availability BAND only. Never a quantity. (§7)
create or replace function public.fn_public_availability(p_product_id uuid, p_minimum int)
returns text
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  -- plpgsql, not SQL: a LANGUAGE sql SECURITY DEFINER body can be inlined by the
  -- planner, and an inlined body is privilege-checked as the caller — which
  -- would make this wrapper demand EXECUTE on fn_on_hand from the public.
  return public.fn_availability(public.fn_on_hand(p_product_id), p_minimum);
end $$;

-- Staff: real quantities are needed at the till (§4), so this one returns the
-- number — but refuses anyone who is not an active owner/staff member. A
-- supplier or customer calling it is rejected, and because the staff views also
-- filter on fn_is_internal(), a supplier gets an empty result rather than an
-- error (the guarded function is never invoked for zero rows).
create or replace function public.fn_staff_on_hand(p_product_id uuid)
returns int
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.fn_is_internal() then
    raise exception 'INTERNAL_ONLY: stock quantities are LuBella operational data' using errcode = '42501';
  end if;
  return public.fn_on_hand(p_product_id);
end $$;

-- ===========================================================================
-- 1. PUBLIC CUSTOMER CATALOG
-- ===========================================================================
-- Exposes: image, name, category, brand, selling price, description,
--          availability band, featured / new flags.
-- Does NOT expose: cost, supplier, supplier identity, margin, stock value,
--          exact quantities, internal ids of suppliers, owner notes.
create or replace view public.public_products
with (security_invoker = false) as
select
  p.id,
  p.product_code,
  p.name,
  p.brand,
  p.description,
  p.keywords,
  p.image_url,
  p.selling_price,
  p.featured,
  p.category_id,
  c.name  as category_name,
  c.slug  as category_slug,
  p.created_at,
  (p.created_at >= now() - interval '30 days') as is_new,
  public.fn_public_availability(p.id, p.minimum_stock) as availability,
  case public.fn_public_availability(p.id, p.minimum_stock)
    when 'OUT' then '🔴 Out of Stock'
    when 'LOW' then '🟡 Low Stock'
    else '🟢 Available'
  end as availability_label
from public.products p
left join public.categories c on c.id = p.category_id
where p.active
  and p.is_public
  and not (p.expiry_date is not null and p.expiry_date < current_date);

create or replace view public.public_categories
with (security_invoker = false) as
select
  c.id, c.name, c.slug, c.description, c.image_url, c.sort_order,
  count(p.id) filter (where p.active and p.is_public) as product_count
from public.categories c
left join public.products p on p.category_id = c.id
where c.active
group by c.id;

-- ===========================================================================
-- 2. STAFF VIEW — real stock numbers, zero cost information
-- ===========================================================================
-- Quantity on hand is operationally necessary at the till. Cost is not, so
-- unit_cost / COGS / payables are simply absent from this view.
create or replace view public.v_staff_products
with (security_invoker = false) as
select
  p.id,
  p.product_code,
  p.name,
  p.category_id,
  c.name as category_name,
  p.brand,
  p.supplier_id,
  s.name as supplier_name,          -- staff may pick a supplier on restock (§27)
  p.image_url,
  p.selling_price,                  -- selling price is explicitly allowed (§4)
  p.minimum_stock,
  p.expiry_date,
  public.fn_expiry_status(p.expiry_date,
    coalesce((public.fn_public_setting('expiry_warning_days', '30'::jsonb))::text::int, 30)) as expiry_status,
  p.description,
  p.active,
  public.fn_staff_on_hand(p.id) as quantity_on_hand,
  public.fn_availability(public.fn_staff_on_hand(p.id), p.minimum_stock) as availability,
  case when public.fn_staff_on_hand(p.id) <= 0 then true else false end as is_out_of_stock,
  case when public.fn_staff_on_hand(p.id) > 0
         and public.fn_staff_on_hand(p.id) <= p.minimum_stock then true else false end as is_low_stock,
  p.created_at,
  p.updated_at
from public.products p
left join public.categories c on c.id = p.category_id
left join public.suppliers s on s.id = p.supplier_id
where public.fn_is_internal();

-- Stock periods are operational schedule information, safe for staff.
create or replace view public.v_staff_stock_periods
with (security_invoker = false) as
select id, label, period_start, period_end, status, closed_at, closed_by, created_at
from public.stock_periods;

-- ===========================================================================
-- 3. SUPPLIER PORTAL VIEWS — hard-filtered to the calling supplier
-- ===========================================================================
-- Every one of these is filtered by fn_current_supplier_id(), which returns
-- NULL for anyone who is not an active supplier user, so an owner, a staff
-- member, or a different supplier sees an empty set. Selling price, LuBella
-- margin, owner notes and other suppliers' rows are absent by construction.
create or replace view public.supplier_portal_orders
with (security_invoker = false) as
select
  sp.id,
  sp.entry_date,
  sp.quantity_sold,
  sp.purchase_cost            as unit_cost,
  sp.payable_amount,
  sp.amount_paid,
  sp.outstanding,
  sp.status,
  sp.is_reversal,
  p.name                      as product_name,
  p.product_code,
  b.batch_number,
  b.received_date
from public.supplier_payables sp
join public.products p on p.id = sp.product_id
join public.purchase_batches b on b.id = sp.purchase_batch_id
where sp.supplier_id = public.fn_current_supplier_id();

create or replace view public.supplier_portal_receipts
with (security_invoker = false) as
select
  b.id,
  b.batch_number,
  b.received_date,
  b.quantity_received,
  b.quantity_sold,
  b.quantity_remaining,
  b.unit_cost,
  b.expiry_date,
  b.cost_status,
  p.name        as product_name,
  p.product_code
from public.purchase_batches b
join public.products p on p.id = b.product_id
where b.supplier_id = public.fn_current_supplier_id();

create or replace view public.supplier_portal_payments
with (security_invoker = false) as
select
  sp.id,
  sp.payment_number,
  sp.amount,
  sp.payment_method,
  sp.payment_date,
  sp.reference,
  sp.notes,
  sp.created_at
from public.supplier_payments sp
where sp.supplier_id = public.fn_current_supplier_id()
  and sp.voided_at is null;

create or replace view public.supplier_portal_statements
with (security_invoker = false) as
select
  st.id, st.statement_number, st.period_month,
  st.opening_outstanding, st.units_sold, st.total_payable, st.total_paid,
  st.outstanding, st.generated_at,
  s.name as supplier_name, s.contact_name, s.phone, s.email, s.address
from public.supplier_statements st
join public.suppliers s on s.id = st.supplier_id
where st.supplier_id = public.fn_current_supplier_id();

create or replace view public.supplier_portal_profile
with (security_invoker = false) as
select
  s.id, s.supplier_code, s.name, s.contact_name, s.phone, s.email, s.address,
  s.tin_number, s.payment_terms, s.active
from public.suppliers s
where s.id = public.fn_current_supplier_id();

-- Supplier dashboard totals, computed from transactions (never typed in).
create or replace view public.supplier_portal_summary
with (security_invoker = false) as
with sid as (select public.fn_current_supplier_id() as supplier_id)
select
  sid.supplier_id,
  (select count(distinct product_id) from public.purchase_batches b
    where b.supplier_id = sid.supplier_id)::int                       as products_supplied,
  (select coalesce(sum(quantity_received), 0) from public.purchase_batches b
    where b.supplier_id = sid.supplier_id)::int                       as units_supplied,
  (select coalesce(sum(quantity_sold), 0) from public.purchase_batches b
    where b.supplier_id = sid.supplier_id)::int                       as units_sold,
  (select coalesce(sum(payable_amount), 0) from public.supplier_payables sp
    where sp.supplier_id = sid.supplier_id)                           as total_payable,
  (select coalesce(sum(amount), 0) from public.supplier_payments pm
    where pm.supplier_id = sid.supplier_id and pm.voided_at is null)  as total_paid,
  (select coalesce(sum(outstanding), 0) from public.supplier_payables sp
    where sp.supplier_id = sid.supplier_id)                           as outstanding,
  (select coalesce(sum(quantity_remaining), 0) from public.purchase_batches b
    where b.supplier_id = sid.supplier_id)::int                       as units_in_stock
from sid;

-- ===========================================================================
-- 4. OWNER FINANCIAL VIEWS (invoker semantics — underlying RLS is owner-only)
-- ===========================================================================

-- Inventory valuation at cost (owner-only information).
create or replace view public.v_owner_inventory
with (security_invoker = false) as
select
  p.id as product_id,
  p.product_code,
  p.name,
  c.name as category_name,
  s.name as supplier_name,
  public.fn_on_hand(p.id) as quantity_on_hand,
  public.fn_avg_unit_cost(p.id) as avg_unit_cost,
  public.fn_money(public.fn_on_hand(p.id) * public.fn_avg_unit_cost(p.id)) as stock_value,
  p.selling_price,
  case when public.fn_avg_unit_cost(p.id) > 0
       then public.fn_money(p.selling_price - public.fn_avg_unit_cost(p.id)) end as unit_margin,
  p.minimum_stock,
  public.fn_availability(public.fn_on_hand(p.id), p.minimum_stock) as availability,
  p.expiry_date,
  public.fn_expiry_status(p.expiry_date,
    coalesce((public.fn_setting('expiry_warning_days', '30'::jsonb))::text::int, 30)) as expiry_status
from public.products p
left join public.categories c on c.id = p.category_id
left join public.suppliers s on s.id = p.supplier_id
where public.fn_is_owner();

-- Monthly P&L. Sales − discounts − returns = net sales; net sales − COGS =
-- gross profit; − operating expenses − staff commission = net profit.
create or replace view public.v_pnl_monthly
with (security_invoker = false) as
with months as (
  select date_trunc('month', sale_date)::date as period_month from public.sales
  union
  select date_trunc('month', expense_date)::date from public.expenses
  union
  select date_trunc('month', sale_date)::date from public.commissions
),
s as (
  select date_trunc('month', sale_date)::date as period_month,
         sum(subtotal)        as gross_sales,
         sum(discount_amount) as discounts,
         sum(returned_amount) as returns,
         sum(total_amount - returned_amount) as net_sales,
         sum(cogs_amount)     as cogs
  from public.sales
  where status <> 'VOIDED'
  group by 1
),
e as (
  select date_trunc('month', expense_date)::date as period_month, sum(amount) as expenses
  from public.expenses group by 1
),
cm as (
  select date_trunc('month', sale_date)::date as period_month, sum(amount) as commission
  from public.commissions group by 1
)
select
  m.period_month,
  public.fn_money(coalesce(s.gross_sales, 0))  as gross_sales,
  public.fn_money(coalesce(s.discounts, 0))    as discounts,
  public.fn_money(coalesce(s.returns, 0))      as returns,
  public.fn_money(coalesce(s.net_sales, 0))    as net_sales,
  public.fn_money(coalesce(s.cogs, 0))         as cogs,
  public.fn_money(coalesce(s.net_sales, 0) - coalesce(s.cogs, 0)) as gross_profit,
  public.fn_money(coalesce(e.expenses, 0))     as operating_expenses,
  public.fn_money(coalesce(cm.commission, 0))  as staff_commission,
  public.fn_money(coalesce(s.net_sales, 0) - coalesce(s.cogs, 0)
                  - coalesce(e.expenses, 0) - coalesce(cm.commission, 0)) as net_profit,
  public.fn_money(greatest(coalesce(s.net_sales, 0) - coalesce(s.cogs, 0)
                  - coalesce(e.expenses, 0) - coalesce(cm.commission, 0), 0) * 0.10) as tithe_due_10pct
from months m
left join s  on s.period_month = m.period_month
left join e  on e.period_month = m.period_month
left join cm on cm.period_month = m.period_month
where public.fn_is_owner()
order by m.period_month desc;

-- Supplier credit book: outstanding per supplier, in transaction terms.
create or replace view public.v_owner_supplier_balance
with (security_invoker = false) as
select
  s.id as supplier_id,
  s.supplier_code,
  s.name,
  coalesce(sum(sp.payable_amount), 0) as total_payable,
  coalesce(sum(sp.amount_paid), 0)    as total_paid,
  coalesce(sum(sp.outstanding), 0)    as outstanding,
  count(sp.id) filter (where sp.status <> 'PAID') as open_lines,
  max(sp.entry_date) as last_activity
from public.suppliers s
left join public.supplier_payables sp on sp.supplier_id = s.id
where public.fn_is_owner()
group by s.id;

-- Supplier payment history (NOT an expense — kept out of the P&L by design).
create or replace view public.v_owner_supplier_payments
with (security_invoker = false) as
select sp.id, sp.payment_number, sp.supplier_id, s.name as supplier_name,
       sp.amount, sp.payment_method, sp.payment_date, sp.reference, sp.notes,
       sp.created_at, sp.voided_at
from public.supplier_payments sp
join public.suppliers s on s.id = sp.supplier_id
where public.fn_is_owner();

-- ----------------------------------------------------------------------------
-- >>> 0009_staff_views.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0009 — Staff-facing views
-- ============================================================================
-- Staff need the operational subset: what is on the shelf, who supplied it,
-- what came in, what they sold themselves, what they earned. They must never
-- reach cost, COGS, payable, margin or valuation. Rather than trusting React
-- to hide those fields, these views are the only staff-readable doorway and the
-- fields simply are not present in them.
-- ============================================================================

-- Supplier picker for the restock form: identity only, no financial columns.
create or replace view public.v_staff_suppliers
with (security_invoker = false) as
select s.id, s.supplier_code, s.name, s.active
from public.suppliers s
where s.active
  and public.fn_is_internal();

-- Receiving history. unit_cost and previous_unit_cost are intentionally absent;
-- cost_flagged only signals "the owner needs to review the price".
create or replace view public.v_staff_restocks
with (security_invoker = false) as
select
  r.id, r.restock_number, r.product_id, p.name as product_name, p.product_code,
  r.supplier_id, s.name as supplier_name,
  r.quantity, r.received_date, r.expiry_date, r.supplier_invoice,
  r.notes, r.cost_pending, r.cost_flagged, r.status,
  r.received_by, u.full_name as received_by_name,
  r.created_at
from public.restocks r
join public.products p on p.id = r.product_id
join public.suppliers s on s.id = r.supplier_id
left join public.app_users u on u.id = r.received_by
where public.fn_is_internal();

-- Own sales. No cogs_amount, no gross_profit, no other staff members' rows.
create or replace view public.v_staff_sales
with (security_invoker = false) as
select
  sa.id, sa.sale_number, sa.sale_date, sa.created_at,
  sa.subtotal, sa.discount_amount, sa.discount_percent, sa.total_amount,
  sa.returned_amount, sa.payment_method, sa.status, sa.staff_id
from public.sales sa
where sa.staff_id = auth.uid()
  and public.fn_is_internal();

-- Own sale lines. unit_price is the selling price (allowed); unit_cogs is not.
create or replace view public.v_staff_sale_items
with (security_invoker = false) as
select
  si.id, si.sale_id, si.product_id, p.name as product_name, p.product_code,
  si.quantity, si.unit_price, si.line_subtotal, si.line_discount, si.line_total,
  si.returned_qty
from public.sale_items si
join public.sales sa on sa.id = si.sale_id
join public.products p on p.id = si.product_id
where sa.staff_id = auth.uid()
  and public.fn_is_internal();

-- Physical count sheet entries: quantities and variance, no valuation columns.
create or replace view public.v_staff_stock_counts
with (security_invoker = false) as
select
  sc.id, sc.stock_period_id, sp.label as period_label,
  sc.product_id, p.name as product_name, p.product_code,
  sc.expected_quantity, sc.counted_quantity, sc.variance,
  sc.status, sc.notes, sc.created_at, sc.confirmed_at
from public.stock_counts sc
join public.stock_periods sp on sp.id = sc.stock_period_id
join public.products p on p.id = sc.product_id
where public.fn_is_internal();

-- Own commission ledger. Other staff members' rows are excluded.
create or replace view public.v_staff_commissions
with (security_invoker = false) as
select
  c.id, c.staff_id, c.sale_id, c.return_id, c.amount, c.rate, c.type,
  c.sale_date, c.note, c.created_at,
  sa.sale_number
from public.commissions c
left join public.sales sa on sa.id = c.sale_id
where c.staff_id = auth.uid()
  and public.fn_is_internal();

create or replace view public.v_staff_commission_payments
with (security_invoker = false) as
select cp.id, cp.payment_number, cp.staff_id, cp.period_start, cp.period_end,
       cp.amount, cp.payment_method, cp.payment_date, cp.reference, cp.notes, cp.created_at
from public.commission_payments cp
where cp.staff_id = auth.uid()
  and public.fn_is_internal();

-- Customer requests are operational for staff too (§4): they may process them,
-- but they see no financial columns (there are none on the table anyway).
create or replace view public.v_staff_customer_requests
with (security_invoker = false) as
select
  cr.id, cr.request_number, cr.customer_name, cr.customer_phone,
  cr.product_id, p.name as product_name, cr.requested_product_name,
  cr.quantity, cr.message, cr.photo_url, cr.source, cr.status,
  cr.was_unavailable, cr.created_at, cr.updated_at
from public.customer_requests cr
left join public.products p on p.id = cr.product_id
where public.fn_is_internal();

-- ----------------------------------------------------------------------------
-- >>> 0010_rls.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0010 — Row Level Security + privileges
-- ============================================================================
-- Strategy: DEFAULT DENY, EXPLICIT ALLOW.
--
--   1. RLS is enabled on every table in `public`.
--   2. Every privilege is revoked from anon/authenticated on every table, view
--      and function — this undoes Supabase's permissive default grants, so a
--      table that nobody thought about ends up invisible rather than exposed.
--   3. Specific grants are handed back to `anon` (catalog + request RPC) and
--      `authenticated` (RLS-scoped reads + RPCs).
--   4. Policies then filter rows by role.
--
-- The result: staff cannot retrieve cost, COGS, payable or valuation data with
-- browser devtools or a raw REST call — the database refuses the request.
-- Supplier A cannot retrieve Supplier B's rows. Customers can reach only the
-- curated public catalog.
-- ============================================================================

-- Roles exist on Supabase; created here so the migrations are portable.
do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then
    create role anon nologin noinherit;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then
    create role authenticated nologin noinherit;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'service_role') then
    create role service_role nologin noinherit bypassrls;
  end if;
end $$;

grant usage on schema public to anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Step 1 & 2: enable RLS everywhere, then strip every default privilege.
-- ---------------------------------------------------------------------------
do $$
declare
  r record;
begin
  for r in
    select c.relname, c.relkind
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind in ('r','p','v','m','f')
  loop
    if r.relkind in ('r','p') then
      execute format('alter table public.%I enable row level security', r.relname);
    end if;
    execute format('revoke all on public.%I from anon, authenticated', r.relname);
  end loop;

  -- Sequences: identity/serial access is only ever needed by definer functions.
  for r in select sequence_name from information_schema.sequences where sequence_schema = 'public'
  loop
    execute format('revoke all on sequence public.%I from anon, authenticated', r.sequence_name);
  end loop;
end $$;

-- Functions default to EXECUTE for PUBLIC, and — importantly — a function
-- created LATER inherits that default again. The blanket revoke below closes it
-- for everything defined so far; 0018_api_grants.sql repeats the revoke after
-- the RPCs exist and then opens only the intended API surface. All function
-- grants live in 0018 so there is exactly one place to audit them.
revoke all on all functions in schema public from public, anon, authenticated;

