-- LuBella  |  Migration 0013 — Finance RPCs
-- ============================================================================
-- Supplier payments, commission payments, expenses, tithe and monthly close.
-- Reminder of the two rules that shape this file (spec §24, §60):
--   * a supplier payment settles a liability recognised in COGS at the time of
--     sale — it is NOT an operating expense and never enters the P&L;
--   * tithe is 10% of NET PROFIT, is never negative, and is also not an expense.
-- ============================================================================

-- ===========================================================================
-- rpc_record_supplier_payment — settles oldest outstanding payables first.
-- ===========================================================================
create or replace function public.rpc_record_supplier_payment(
  p_supplier_id    uuid,
  p_amount         numeric,
  p_payment_method public.payment_method,
  p_payment_date   date default current_date,
  p_reference      text default null,
  p_notes          text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user       public.app_users;
  v_payment_id uuid;
  v_number     text;
  v_remaining  numeric;
  v_alloc      numeric;
  v_line       record;
  v_balance    numeric;
  v_allocations jsonb := '[]'::jsonb;
  v_applied    numeric := 0;
begin
  v_user := public.fn_current_user_row();
  perform public.fn_require_owner();
  perform public.fn_require_open_period(p_payment_date);

  if coalesce(p_amount, 0) <= 0 then
    raise exception 'AMOUNT_INVALID: a payment must be greater than zero' using errcode = '22023';
  end if;

  select coalesce(sum(outstanding), 0) into v_balance
  from public.supplier_payables where supplier_id = p_supplier_id;

  if v_balance <= 0 then
    raise exception 'NOTHING_OUTSTANDING: this supplier has no outstanding balance to pay'
      using errcode = '22023';
  end if;
  if p_amount > v_balance then
    raise exception 'OVERPAYMENT: the outstanding balance is % but % was entered. Cards must not hold supplier credit.',
      v_balance, p_amount using errcode = '22023';
  end if;

  v_number := public.fn_next_number('SP', 6);
  v_remaining := public.fn_money(p_amount);

  insert into public.supplier_payments (payment_number, supplier_id, amount, payment_method,
                                        payment_date, reference, notes, created_by)
  values (v_number, p_supplier_id, public.fn_money(p_amount), p_payment_method,
          p_payment_date, p_reference, p_notes, v_user.id)
  returning id into v_payment_id;

  -- Oldest outstanding first.
  for v_line in
    select * from public.supplier_payables
    where supplier_id = p_supplier_id and outstanding > 0
    order by entry_date asc, created_at asc, id asc
    for update
  loop
    exit when v_remaining <= 0;

    v_alloc := least(v_remaining, v_line.outstanding);

    insert into public.supplier_payment_allocations (payment_id, payable_id, amount)
    values (v_payment_id, v_line.id, v_alloc);

    update public.supplier_payables
       set amount_paid = public.fn_money(amount_paid + v_alloc),
           outstanding = public.fn_money(payable_amount - (amount_paid + v_alloc)),
           status = case when public.fn_money(payable_amount - (amount_paid + v_alloc)) <= 0
                         then 'PAID'::public.payable_status
                         else 'PARTIAL'::public.payable_status end
     where id = v_line.id;

    v_allocations := v_allocations || jsonb_build_object(
      'payable_id', v_line.id, 'batch_id', v_line.purchase_batch_id,
      'quantity_sold', v_line.quantity_sold, 'amount', v_alloc);

    v_remaining := public.fn_money(v_remaining - v_alloc);
    v_applied := public.fn_money(v_applied + v_alloc);
  end loop;

  perform public.fn_audit('SUPPLIER_PAYMENT', 'supplier_payments', v_payment_id, null,
    jsonb_build_object('payment_number', v_number, 'supplier_id', p_supplier_id,
                       'amount', p_amount, 'payment_method', p_payment_method,
                       'payment_date', p_payment_date, 'reference', p_reference,
                       'allocations', v_allocations,
                       'note', 'Supplier payments are a balance-sheet settlement, not an operating expense'));

  return jsonb_build_object(
    'payment_id', v_payment_id, 'payment_number', v_number,
    'amount', public.fn_money(p_amount), 'applied', v_applied,
    'remaining_outstanding', public.fn_money(
      (select coalesce(sum(outstanding), 0) from public.supplier_payables where supplier_id = p_supplier_id)),
    'allocations', v_allocations
  );
end $$;

-- ===========================================================================
-- rpc_generate_supplier_statement — totals RECOMPUTED from transactions.
-- Nothing is ever typed into a statement (spec §21).
-- ===========================================================================
create or replace function public.rpc_generate_supplier_statement(
  p_supplier_id uuid,
  p_month       date
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user      public.app_users;
  v_month     date := date_trunc('month', p_month)::date;
  v_prev      date := (date_trunc('month', p_month) - interval '1 month')::date;
  v_opening   numeric := 0;
  v_units     int := 0;
  v_payable   numeric := 0;
  v_paid      numeric := 0;
  v_stmt_id   uuid;
  v_number    text;
  v_outstanding numeric := 0;
begin
  v_user := public.fn_current_user_row();
  perform public.fn_require_owner();

  if not exists (select 1 from public.suppliers where id = p_supplier_id) then
    raise exception 'SUPPLIER_NOT_FOUND: no supplier with id %', p_supplier_id using errcode = '23503';
  end if;

  -- Opening = everything that had been recognised up to the end of last month,
  -- minus everything paid up to the end of last month. Derived, not entered.
  select coalesce(sum(payable_amount), 0), coalesce(sum(amount_paid), 0)
    into v_payable, v_paid
  from public.supplier_payables
  where supplier_id = p_supplier_id and entry_date < v_month;

  v_opening := public.fn_money(v_payable - v_paid);

  -- This month's activity, straight from the payable lines that FIFO created.
  select coalesce(sum(payable_amount), 0), coalesce(sum(quantity_sold), 0)
    into v_payable, v_units
  from public.supplier_payables
  where supplier_id = p_supplier_id
    and entry_date >= v_month
    and entry_date < (v_month + interval '1 month')::date
    and is_reversal = false;

  select coalesce(sum(amount), 0) into v_paid
  from public.supplier_payments
  where supplier_id = p_supplier_id
    and payment_date >= v_month
    and payment_date < (v_month + interval '1 month')::date
    and voided_at is null;

  v_outstanding := public.fn_money(v_opening + v_payable - v_paid);
  v_number := public.fn_next_number('ST', 5);

  insert into public.supplier_statements
    (statement_number, supplier_id, period_month, opening_outstanding, units_sold,
     total_payable, total_paid, outstanding, generated_by)
  values (v_number, p_supplier_id, v_month, v_opening, coalesce(v_units, 0),
          public.fn_money(v_payable), public.fn_money(v_paid), v_outstanding, v_user.id)
  on conflict (supplier_id, period_month) do update
    set opening_outstanding = excluded.opening_outstanding,
        units_sold          = excluded.units_sold,
        total_payable       = excluded.total_payable,
        total_paid          = excluded.total_paid,
        outstanding         = excluded.outstanding,
        generated_at        = now(),
        generated_by        = excluded.generated_by
  returning id into v_stmt_id;

  perform public.fn_audit('SUPPLIER_STATEMENT_GENERATE', 'supplier_statements', v_stmt_id, null,
    jsonb_build_object('statement_number', v_number, 'supplier_id', p_supplier_id,
                       'period_month', v_month, 'opening_outstanding', v_opening,
                       'units_sold', coalesce(v_units, 0), 'total_payable', v_payable,
                       'total_paid', v_paid, 'outstanding', v_outstanding));

  return jsonb_build_object(
    'statement_id', v_stmt_id, 'statement_number', v_number, 'period_month', v_month,
    'opening_outstanding', v_opening, 'units_sold', coalesce(v_units, 0),
    'total_payable', public.fn_money(v_payable), 'total_paid', public.fn_money(v_paid),
    'outstanding', v_outstanding
  );
end $$;

-- ===========================================================================
-- Commission payments
-- ===========================================================================
create or replace function public.rpc_record_commission_payment(
  p_staff_id       uuid,
  p_amount         numeric,
  p_period_start   date,
  p_period_end     date,
  p_payment_method public.payment_method,
  p_payment_date   date default current_date,
  p_reference      text default null,
  p_notes          text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user     public.app_users;
  v_earned   numeric;
  v_paid     numeric;
  v_due      numeric;
  v_id       uuid;
  v_number   text;
begin
  v_user := public.fn_current_user_row();
  perform public.fn_require_owner();
  perform public.fn_require_open_period(p_payment_date);

  if coalesce(p_amount, 0) <= 0 then
    raise exception 'AMOUNT_INVALID: a commission payment must be greater than zero' using errcode = '22023';
  end if;

  select coalesce(sum(amount), 0) into v_earned
  from public.commissions
  where staff_id = p_staff_id and sale_date between p_period_start and p_period_end;

  select coalesce(sum(amount), 0) into v_paid
  from public.commission_payments
  where staff_id = p_staff_id;

  v_due := public.fn_money(v_earned - v_paid);
  if p_amount > v_due then
    raise exception 'OVERPAYMENT: commission due for this period is % but % was entered', v_due, p_amount
      using errcode = '22023';
  end if;

  v_number := public.fn_next_number('CP', 6);

  insert into public.commission_payments (payment_number, staff_id, period_start, period_end,
                                          amount, payment_method, payment_date, reference, notes, created_by)
  values (v_number, p_staff_id, p_period_start, p_period_end, public.fn_money(p_amount),
          p_payment_method, p_payment_date, p_reference, p_notes, v_user.id)
  returning id into v_id;

  perform public.fn_audit('COMMISSION_PAYMENT', 'commission_payments', v_id, null,
    jsonb_build_object('payment_number', v_number, 'staff_id', p_staff_id, 'amount', p_amount,
                       'period_start', p_period_start, 'period_end', p_period_end));

  return jsonb_build_object('payment_id', v_id, 'payment_number', v_number,
                            'amount', public.fn_money(p_amount),
                            'remaining_due', public.fn_money(v_due - p_amount));
end $$;

-- ===========================================================================
-- Expenses (owner-only)
-- ===========================================================================
create or replace function public.rpc_record_expense(
  p_category       public.expense_category,
  p_amount         numeric,
  p_payment_method public.payment_method,
  p_expense_date   date default current_date,
  p_description    text default null,
  p_receipt_url    text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user   public.app_users;
  v_id     uuid;
  v_number text;
begin
  v_user := public.fn_current_user_row();
  perform public.fn_require_owner();
  perform public.fn_require_open_period(p_expense_date);

  if coalesce(p_amount, 0) <= 0 then
    raise exception 'AMOUNT_INVALID: an expense must be greater than zero' using errcode = '22023';
  end if;

  v_number := public.fn_next_number('EXP', 6);

  insert into public.expenses (expense_number, category, amount, payment_method, expense_date,
                               description, receipt_url, created_by)
  values (v_number, p_category, public.fn_money(p_amount), p_payment_method, p_expense_date,
          p_description, p_receipt_url, v_user.id)
  returning id into v_id;

  perform public.fn_audit('EXPENSE_RECORD', 'expenses', v_id, null,
    jsonb_build_object('expense_number', v_number, 'category', p_category, 'amount', p_amount,
                       'payment_method', p_payment_method, 'expense_date', p_expense_date,
                       'description', p_description));

  return jsonb_build_object('expense_id', v_id, 'expense_number', v_number,
                            'amount', public.fn_money(p_amount));
end $$;

create or replace function public.rpc_delete_expense(p_expense_id uuid, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_exp public.expenses;
begin
  perform public.fn_require_owner();

  select * into v_exp from public.expenses where id = p_expense_id;
  if not found then
    raise exception 'EXPENSE_NOT_FOUND: no expense with id %', p_expense_id using errcode = '23503';
  end if;
  perform public.fn_require_open_period(v_exp.expense_date);

  -- Financial history is not destroyed: the row is voided by deleting it only
  -- after the audit entry captures it in full. (spec §53: financial history
  -- must never be destructively deleted without a trace.)
  perform public.fn_audit('EXPENSE_DELETE', 'expenses', p_expense_id, to_jsonb(v_exp), null, p_reason);
  delete from public.expenses where id = p_expense_id;

  return jsonb_build_object('expense_id', p_expense_id, 'deleted', true);
end $$;

-- ===========================================================================
-- rpc_compute_tithe — derived from the P&L, never typed in.
-- ===========================================================================
create or replace function public.rpc_compute_tithe(
  p_month date default current_date
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user   public.app_users;
  v_month  date := date_trunc('month', p_month)::date;
  v_pnl    record;
  v_rate   numeric;
  v_amount numeric;
  v_id     uuid;
begin
  v_user := public.fn_current_user_row();
  perform public.fn_require_owner();

  select * into v_pnl from public.v_pnl_monthly where period_month = v_month;
  if not found then
    return jsonb_build_object('period_month', v_month, 'net_profit', 0, 'tithe_amount', 0,
                              'status', 'DUE', 'message', 'No financial activity in this month yet.');
  end if;

  v_rate := coalesce((public.fn_setting('tithe_rate', '0.10'::jsonb))::text::numeric, 0.10);

  -- Tithe on NET PROFIT; a loss produces no tithe (spec §41).
  v_amount := case when v_pnl.net_profit > 0
                   then public.fn_money(v_pnl.net_profit * v_rate) else 0 end;

  insert into public.tithe_records (period_month, net_profit, tithe_rate, tithe_amount, created_by)
  values (v_month, v_pnl.net_profit, v_rate, v_amount, v_user.id)
  on conflict (period_month) do update
    set net_profit = excluded.net_profit,
        tithe_rate = excluded.tithe_rate,
        tithe_amount = case when tithe_records.status = 'PAID' then tithe_records.tithe_amount
                            else excluded.tithe_amount end
  returning id into v_id;

  perform public.fn_audit('TITHE_COMPUTE', 'tithe_records', v_id, null,
    jsonb_build_object('period_month', v_month, 'net_profit', v_pnl.net_profit,
                       'tithe_rate', v_rate, 'tithe_amount', v_amount));

  return jsonb_build_object(
    'period_month', v_month, 'net_profit', v_pnl.net_profit, 'tithe_rate', v_rate,
    'tithe_amount', v_amount, 'status',
    (select status from public.tithe_records where id = v_id),
    'message', case when v_pnl.net_profit > 0 then null else 'No tithe due' end
  );
end $$;

create or replace function public.rpc_record_tithe_payment(
  p_period_month   date,
  p_payment_method public.payment_method,
  p_paid_date      date default current_date,
  p_reference      text default null,
  p_notes          text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user  public.app_users;
  v_rec   public.tithe_records;
begin
  v_user := public.fn_current_user_row();
  perform public.fn_require_owner();

  select * into v_rec from public.tithe_records
   where period_month = date_trunc('month', p_period_month)::date for update;
  if not found then
    raise exception 'TITHE_NOT_FOUND: compute the tithe for that month first' using errcode = '23503';
  end if;
  if v_rec.status = 'PAID' then
    raise exception 'ALREADY_PAID: tithe for % is already recorded as paid',
      to_char(v_rec.period_month, 'Mon YYYY') using errcode = '22023';
  end if;

  update public.tithe_records
     set status = 'PAID', paid_date = p_paid_date, payment_method = p_payment_method,
         reference = p_reference, notes = p_notes
   where id = v_rec.id;

  perform public.fn_audit('TITHE_PAYMENT', 'tithe_records', v_rec.id,
    jsonb_build_object('status', v_rec.status),
    jsonb_build_object('status', 'PAID', 'amount', v_rec.tithe_amount,
                       'paid_date', p_paid_date, 'payment_method', p_payment_method,
                       'reference', p_reference));

  -- Reminder: tithe is NOT an operating expense and never enters the P&L; it is
  -- an appropriation of net profit, which is why it is applied here and not in
  -- v_pnl_monthly.
  return jsonb_build_object('tithe_id', v_rec.id, 'amount', v_rec.tithe_amount, 'status', 'PAID',
    'note', 'Tithe is an appropriation of net profit, not an operating expense.');
end $$;

-- ===========================================================================
-- Monthly close (spec §54)
-- ===========================================================================
create or replace function public.rpc_close_month(
  p_month date default current_date,
  p_notes text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user  public.app_users;
  v_month date := date_trunc('month', p_month)::date;
  v_pnl   record;
  v_id    uuid;
begin
  v_user := public.fn_current_user_row();
  perform public.fn_require_owner();

  select * into v_pnl from public.v_pnl_monthly where period_month = v_month;

  insert into public.period_closes (period_month, status, net_sales, cogs, gross_profit,
                                    expenses, commission, net_profit, closed_by, closed_at, notes)
  values (v_month, 'CLOSED', coalesce(v_pnl.net_sales, 0), coalesce(v_pnl.cogs, 0),
          coalesce(v_pnl.gross_profit, 0), coalesce(v_pnl.operating_expenses, 0),
          coalesce(v_pnl.staff_commission, 0), coalesce(v_pnl.net_profit, 0),
          v_user.id, now(), p_notes)
  on conflict (period_month) do update
    set status = 'CLOSED', net_sales = excluded.net_sales, cogs = excluded.cogs,
        gross_profit = excluded.gross_profit, expenses = excluded.expenses,
        commission = excluded.commission, net_profit = excluded.net_profit,
        closed_by = excluded.closed_by, closed_at = now(), notes = excluded.notes
  returning id into v_id;

  perform public.fn_audit('MONTH_CLOSE', 'period_closes', v_id, null,
    jsonb_build_object('period_month', v_month, 'net_sales', v_pnl.net_sales,
                       'cogs', v_pnl.cogs, 'net_profit', v_pnl.net_profit, 'notes', p_notes));

  return jsonb_build_object('period_close_id', v_id, 'period_month', v_month, 'status', 'CLOSED',
                            'net_profit', coalesce(v_pnl.net_profit, 0));
end $$;

create or replace function public.rpc_reopen_month(p_month date, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user  public.app_users;
  v_month date := date_trunc('month', p_month)::date;
begin
  v_user := public.fn_current_user_row();
  perform public.fn_require_owner();

  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'REASON_REQUIRED: reopening a closed month must record a reason' using errcode = '22023';
  end if;

  update public.period_closes
     set status = 'OPEN', reopened_at = now(), reopened_by = v_user.id,
         notes = concat_ws(E'\n', notes, 'Reopened: ' || p_reason)
   where period_month = v_month;

  if not found then
    raise exception 'MONTH_NOT_FOUND: % is not closed', to_char(v_month, 'Mon YYYY') using errcode = '23503';
  end if;

  perform public.fn_audit('MONTH_REOPEN', 'period_closes', null,
    jsonb_build_object('period_month', v_month, 'status', 'CLOSED'),
    jsonb_build_object('period_month', v_month, 'status', 'OPEN', 'reason', p_reason));

  return jsonb_build_object('period_month', v_month, 'status', 'OPEN');
end $$;

-- ----------------------------------------------------------------------------
-- >>> 0014_rpcs_customer.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0014 — Customer portal RPCs (open to `anon`)
-- ============================================================================
-- Customers never register. The public write surface is exactly ONE function,
-- and it deliberately cannot touch inventory: a WhatsApp/Telegram order is a
-- REQUEST, and stock only ever leaves through rpc_complete_sale (spec §9, §60).
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Public catalog search. Server-side filtering so the browser never needs a
-- broad table grant and the catalog stays fast on a phone.
-- ---------------------------------------------------------------------------
create or replace function public.rpc_public_catalog(
  p_search      text default null,
  p_category_id uuid default null,
  p_brand       text default null,
  p_featured    boolean default null,
  p_limit       int default 60,
  p_offset      int default 0
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
  v_total int;
begin
  with filtered as (
    select pp.*
    from public.public_products pp
    where (p_category_id is null or pp.category_id = p_category_id)
      and (p_brand is null or pp.brand = p_brand)
      and (p_featured is null or pp.featured = p_featured)
      and (
        p_search is null or btrim(p_search) = ''
        or pp.name ilike '%' || btrim(p_search) || '%'
        or coalesce(pp.brand, '')     ilike '%' || btrim(p_search) || '%'
        or coalesce(pp.keywords, '')  ilike '%' || btrim(p_search) || '%'
        or coalesce(pp.description, '') ilike '%' || btrim(p_search) || '%'
        or coalesce(pp.category_name, '') ilike '%' || btrim(p_search) || '%'
        or coalesce(pp.product_code, '') ilike '%' || btrim(p_search) || '%'
      )
  )
  select coalesce(jsonb_agg(to_jsonb(f) order by
           case when p_featured is true then f.featured end desc nulls last,
           case f.availability when 'AVAILABLE' then 0 when 'LOW' then 1 else 2 end,
           f.created_at desc), '[]'::jsonb),
         count(*)
    into v_items, v_total
  from (select * from filtered order by created_at desc
        limit greatest(coalesce(p_limit, 60), 1) offset greatest(coalesce(p_offset, 0), 0)) f;

  return jsonb_build_object('items', v_items, 'count', v_total,
                            'limit', p_limit, 'offset', p_offset);
end $$;

-- Brands and categories for the filter bar.
create or replace function public.rpc_public_filters()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
    'categories', coalesce((select jsonb_agg(jsonb_build_object(
        'id', c.id, 'name', c.name, 'slug', c.slug, 'product_count', c.product_count)
        order by c.sort_order, c.name)
      from public.public_categories c), '[]'::jsonb),
    'brands', coalesce((select jsonb_agg(distinct b) from (
        select b from (select distinct brand as b from public.public_products where brand is not null) x
        order by b) y), '[]'::jsonb),
    'settings', public.fn_public_settings()
  );
$$;

-- ---------------------------------------------------------------------------
-- Building an order message. Server-side so the WhatsApp number lives in
-- settings, never in a component (spec §14).
-- ---------------------------------------------------------------------------
create or replace function public.rpc_build_order_message(
  p_items jsonb,               -- [{"product_id":"…","quantity":2}, …]
  p_customer_name text default null,
  p_customer_phone text default null
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb := '[]'::jsonb;
  v_total numeric := 0;
  v_line  record;
  v_msg   text;
  v_links jsonb;
begin
  for v_line in
    select pp.id, pp.name, pp.selling_price, pp.availability,
           greatest(sum((e ->> 'quantity')::int), 0) as quantity
    from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) e
    join public.public_products pp on pp.id = (e ->> 'product_id')::uuid
    group by pp.id, pp.name, pp.selling_price, pp.availability
    order by pp.name
  loop
    continue when v_line.quantity <= 0;
    v_items := v_items || jsonb_build_object(
      'product_id', v_line.id, 'name', v_line.name, 'quantity', v_line.quantity,
      'unit_price', v_line.selling_price,
      'line_total', public.fn_money(v_line.quantity * v_line.selling_price),
      'availability', v_line.availability
    );
    -- The estimate is shown to the customer but is explicitly not a confirmed
    -- price; stock is not reserved or deducted at this point.
    v_total := v_total + public.fn_money(v_line.quantity * v_line.selling_price);
  end loop;

  v_msg := public.fn_build_order_message(v_items, v_total, p_customer_name, p_customer_phone, 'ORDER');
  v_links := public.fn_contact_links(v_msg);

  return jsonb_build_object(
    'items', v_items,
    'estimated_total', public.fn_money(v_total),
    'estimate_note', 'This total is an estimate only until LuBella confirms your order.',
    'message', v_msg,
    'links', v_links
  );
end $$;

-- ---------------------------------------------------------------------------
-- rpc_submit_customer_request — the single public write path.
-- Records demand (including for products we do not stock at all) and returns
-- ready-to-send WhatsApp/Telegram links. It NEVER touches stock.
-- ---------------------------------------------------------------------------
create or replace function public.rpc_submit_customer_request(
  p_requested_product_name text,
  p_quantity               int default 1,
  p_customer_name          text default null,
  p_customer_phone         text default null,
  p_product_id             uuid default null,
  p_message                text default null,
  p_photo_url              text default null,
  p_source                 public.request_source default 'WEBSITE'
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id       uuid;
  v_number   text;
  v_prod     public.products;
  v_available int;
  v_unavail  boolean := false;
  v_links    jsonb;
  v_msg      text;
  v_hash     text;
  v_recent   int;
begin
  if p_requested_product_name is null or btrim(p_requested_product_name) = '' then
    raise exception 'PRODUCT_REQUIRED: tell us which product you would like' using errcode = '22023';
  end if;
  if coalesce(p_quantity, 0) <= 0 then
    raise exception 'QUANTITY_INVALID: quantity must be greater than zero' using errcode = '22023';
  end if;
  if p_customer_phone is null or length(regexp_replace(p_customer_phone, '[^0-9]', '', 'g')) < 7 then
    raise exception 'PHONE_REQUIRED: a phone number is needed so LuBella can reach you' using errcode = '22023';
  end if;

  -- Light anti-spam guard on a public endpoint: 5 requests per phone per hour.
  -- md5 (pg_catalog, always available) rather than pgcrypto's digest(): RPCs pin
  -- search_path to public+pg_temp, so a function living in the `extensions`
  -- schema is not resolvable. This is a privacy measure — the rate-limit table
  -- stores a one-way key, never the customer's phone number — not a password
  -- hash, so md5's properties are sufficient here.
  v_hash := md5(regexp_replace(p_customer_phone, '[^0-9]', '', 'g'));
  select count(*) into v_recent from public.request_rate_limit
   where phone_hash = v_hash and created_at > now() - interval '1 hour';
  if v_recent >= 5 then
    raise exception 'RATE_LIMITED: too many requests from this number. Please contact LuBella directly.'
      using errcode = '22023';
  end if;
  insert into public.request_rate_limit (phone_hash) values (v_hash);

  if p_product_id is not null then
    select * into v_prod from public.products where id = p_product_id;
    if found then
      v_available := public.fn_on_hand(p_product_id);
      v_unavail := v_available <= 0
                   or (v_prod.expiry_date is not null and v_prod.expiry_date < current_date);
    end if;
  end if;

  v_number := public.fn_next_number('CR', 4);

  insert into public.customer_requests (
    request_number, customer_name, customer_phone, product_id, requested_product_name,
    quantity, message, photo_url, source, was_unavailable, category_id
  ) values (
    v_number, p_customer_name, p_customer_phone, p_product_id, btrim(p_requested_product_name),
    p_quantity, p_message, p_photo_url, p_source, v_unavail,
    case when p_product_id is not null then (select category_id from public.products where id = p_product_id) end
  ) returning id into v_id;

  v_msg := public.fn_build_order_message(
    jsonb_build_array(jsonb_build_object('name', btrim(p_requested_product_name), 'quantity', p_quantity)),
    null, p_customer_name, p_customer_phone, 'REQUEST');
  v_links := public.fn_contact_links(v_msg);

  -- NOTE: no stock movement is written here. Inventory is only ever reduced by
  -- rpc_complete_sale (spec §9).
  return jsonb_build_object(
    'request_id', v_id, 'request_number', v_number,
    'was_unavailable', v_unavail,
    'message', v_msg, 'links', v_links
  );
end $$;

-- ---------------------------------------------------------------------------
-- Customer request management (internal)
-- ---------------------------------------------------------------------------
create or replace function public.rpc_update_request_status(
  p_request_id uuid,
  p_status     public.request_status,
  p_note       text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_req public.customer_requests;
  v_user public.app_users;
begin
  v_user := public.fn_current_user_row();
  perform public.fn_require_internal();

  select * into v_req from public.customer_requests where id = p_request_id for update;
  if not found then
    raise exception 'REQUEST_NOT_FOUND: no request with id %', p_request_id using errcode = '23503';
  end if;

  update public.customer_requests
     set status = p_status, owner_note = coalesce(p_note, owner_note)
   where id = p_request_id;

  perform public.fn_audit('CUSTOMER_REQUEST_STATUS', 'customer_requests', p_request_id,
    jsonb_build_object('status', v_req.status),
    jsonb_build_object('status', p_status, 'note', p_note,
                       'request_number', v_req.request_number,
                       'changed_by', v_user.full_name));

  return jsonb_build_object('request_id', p_request_id, 'request_number', v_req.request_number,
                            'status', p_status);
end $$;

-- Who asked for a product that is not on the shelf — used to prompt the owner
-- at purchasing time: «12 customers have requested this product.»
create or replace function public.rpc_demand_for_product(p_product_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
    'request_count', count(*),
    'unique_customers', count(distinct cr.customer_phone),
    'last_requested', max(cr.created_at),
    'message', count(*) || ' customer' || case when count(*) = 1 then '' else 's' end ||
               ' have requested this product.'
  )
  from public.customer_requests cr
  where cr.product_id = p_product_id
    and cr.status <> 'CANCELLED';
$$;

-- ----------------------------------------------------------------------------
-- >>> 0015_rpcs_admin.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0015 — Administration RPCs
-- ============================================================================
-- Staff & supplier accounts, categories, settings, audit queries, backups.
-- Account creation is two-step by design: the Auth user is created with the
-- service key (edge function / gateway), then linked here. The anon key alone
-- can never mint a privileged account.
-- ============================================================================

-- ===========================================================================
-- Staff
-- ===========================================================================
create or replace function public.rpc_register_app_user(
  p_user_id       uuid,
  p_email         text,
  p_full_name     text,
  p_role          public.user_role,
  p_phone         text default null,
  p_commission_rate numeric default 0.03
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user public.app_users;
begin
  v_user := public.fn_current_user_row();

  -- The very first account bootstraps the shop and must be the Owner.
  if not exists (select 1 from public.app_users where role = 'OWNER') then
    if p_role <> 'OWNER' then
      raise exception 'BOOTSTRAP: the first account must be the OWNER' using errcode = '42501';
    end if;
  else
    perform public.fn_require_owner();
    if p_role = 'OWNER' and v_user.id is null then
      raise exception 'OWNER_ONLY: cannot create a second owner from the API' using errcode = '42501';
    end if;
  end if;

  insert into public.app_users (id, email, full_name, phone, role, commission_rate, created_by)
  values (p_user_id, lower(btrim(p_email)), btrim(p_full_name), p_phone, p_role,
          case when p_role = 'OWNER' then 0 else coalesce(p_commission_rate, 0.03) end,
          v_user.id)
  on conflict (id) do update
    set email = excluded.email, full_name = excluded.full_name, role = excluded.role,
        phone = excluded.phone, commission_rate = excluded.commission_rate
  returning * into v_user;

  perform public.fn_audit('APP_USER_REGISTER', 'app_users', v_user.id, null,
    jsonb_build_object('email', v_user.email, 'role', v_user.role,
                       'commission_rate', v_user.commission_rate));

  return jsonb_build_object('user_id', v_user.id, 'role', v_user.role, 'email', v_user.email);
end $$;

create or replace function public.rpc_update_staff(
  p_user_id         uuid,
  p_full_name       text default null,
  p_phone           text default null,
  p_commission_rate numeric default null,
  p_active          boolean default null,
  p_note            text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_before public.app_users;
  v_after  public.app_users;
begin
  perform public.fn_require_owner();

  select * into v_before from public.app_users where id = p_user_id for update;
  if not found then
    raise exception 'USER_NOT_FOUND: no user with id %', p_user_id using errcode = '23503';
  end if;
  if v_before.role = 'OWNER' and p_active = false then
    raise exception 'OWNER_PROTECTED: the owner account cannot be deactivated' using errcode = '42501';
  end if;

  update public.app_users
     set full_name = coalesce(p_full_name, full_name),
         phone = coalesce(p_phone, phone),
         -- commission rate is clamped to the contractual maximum of 3%
         commission_rate = case when p_commission_rate is null then commission_rate
                                else least(greatest(p_commission_rate, 0), 0.03) end,
         active = coalesce(p_active, active),
         note = coalesce(p_note, note)
   where id = p_user_id
  returning * into v_after;

  perform public.fn_audit(
    case when v_before.active and not v_after.active then 'STAFF_DEACTIVATE'
         when not v_before.active and v_after.active then 'STAFF_ACTIVATE'
         else 'STAFF_UPDATE' end,
    'app_users', p_user_id,
    jsonb_build_object('full_name', v_before.full_name, 'active', v_before.active,
                       'commission_rate', v_before.commission_rate),
    jsonb_build_object('full_name', v_after.full_name, 'active', v_after.active,
                       'commission_rate', v_after.commission_rate, 'note', p_note));

  return jsonb_build_object('user_id', p_user_id, 'active', v_after.active,
                            'commission_rate', v_after.commission_rate);
end $$;

-- ===========================================================================
-- Suppliers
-- ===========================================================================
create or replace function public.rpc_upsert_supplier(
  p_name         text,
  p_supplier_id  uuid default null,
  p_contact_name text default null,
  p_phone        text default null,
  p_email        text default null,
  p_address      text default null,
  p_tin_number   text default null,
  p_payment_terms text default null,
  p_active       boolean default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
  v_code text;
  v_before public.suppliers;
begin
  perform public.fn_require_owner();

  if p_supplier_id is null then
    v_code := public.fn_next_number('SUP', 4);
    insert into public.suppliers (supplier_code, name, contact_name, phone, email, address,
                                  tin_number, payment_terms)
    values (v_code, btrim(p_name), p_contact_name, p_phone, p_email, p_address,
            p_tin_number, coalesce(p_payment_terms, 'Monthly settlement on units sold'))
    returning id into v_id;
  else
    select * into v_before from public.suppliers where id = p_supplier_id;
    if not found then
      raise exception 'SUPPLIER_NOT_FOUND: no supplier with id %', p_supplier_id using errcode = '23503';
    end if;
    update public.suppliers
       set name = coalesce(p_name, name), contact_name = coalesce(p_contact_name, contact_name),
           phone = coalesce(p_phone, phone), email = coalesce(p_email, email),
           address = coalesce(p_address, address), tin_number = coalesce(p_tin_number, tin_number),
           payment_terms = coalesce(p_payment_terms, payment_terms),
           active = coalesce(p_active, active)
     where id = p_supplier_id
    returning id into v_id;
    v_code := v_before.supplier_code;
  end if;

  perform public.fn_audit('SUPPLIER_' ||
      case when p_supplier_id is null then 'CREATE' else 'UPDATE' end,
    'suppliers', v_id, case when p_supplier_id is null then null else to_jsonb(v_before) end,
    jsonb_build_object('name', p_name, 'code', v_code, 'active', p_active));

  return jsonb_build_object('supplier_id', v_id, 'supplier_code', v_code);
end $$;

-- Links an existing Auth user to a supplier. Only the owner can do this, and a
-- supplier user can belong to exactly one supplier.
create or replace function public.rpc_link_supplier_user(
  p_supplier_id uuid,
  p_user_id     uuid,
  p_status      public.supplier_user_status default 'ACTIVE'
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
  v_user public.app_users;
begin
  perform public.fn_require_owner();

  select * into v_user from public.app_users where id = p_user_id;
  if not found then
    raise exception 'USER_NOT_FOUND: register the account first (rpc_register_app_user)' using errcode = '23503';
  end if;
  if v_user.role <> 'SUPPLIER' then
    raise exception 'WRONG_ROLE: a supplier login must have the SUPPLIER role' using errcode = '22023';
  end if;
  if exists (select 1 from public.supplier_users where user_id = p_user_id and supplier_id <> p_supplier_id) then
    raise exception 'ALREADY_LINKED: this login is already linked to a different supplier' using errcode = '22023';
  end if;

  insert into public.supplier_users (supplier_id, user_id, status)
  values (p_supplier_id, p_user_id, p_status)
  on conflict (supplier_id, user_id) do update set status = excluded.status
  returning id into v_id;

  perform public.fn_audit('SUPPLIER_USER_LINK', 'supplier_users', v_id, null,
    jsonb_build_object('supplier_id', p_supplier_id, 'user_id', p_user_id, 'status', p_status));

  return jsonb_build_object('supplier_user_id', v_id, 'status', p_status);
end $$;

create or replace function public.rpc_set_supplier_user_status(
  p_supplier_user_id uuid,
  p_status           public.supplier_user_status
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_before public.supplier_users;
begin
  perform public.fn_require_owner();
  select * into v_before from public.supplier_users where id = p_supplier_user_id for update;
  if not found then
    raise exception 'LINK_NOT_FOUND: no supplier account link with id %', p_supplier_user_id using errcode = '23503';
  end if;

  update public.supplier_users set status = p_status where id = p_supplier_user_id;

  perform public.fn_audit('SUPPLIER_USER_' || case when p_status = 'ACTIVE' then 'ACTIVATE' else 'DEACTIVATE' end,
    'supplier_users', p_supplier_user_id,
    jsonb_build_object('status', v_before.status), jsonb_build_object('status', p_status));

  return jsonb_build_object('supplier_user_id', p_supplier_user_id, 'status', p_status);
end $$;

create or replace function public.rpc_add_supplier_note(p_supplier_id uuid, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user public.app_users;
  v_id uuid;
begin
  v_user := public.fn_current_user_row();
  perform public.fn_require_owner();
  insert into public.supplier_internal_notes (supplier_id, note, created_by)
  values (p_supplier_id, p_note, v_user.id) returning id into v_id;
  perform public.fn_audit('SUPPLIER_NOTE_ADD', 'supplier_internal_notes', v_id, null,
    jsonb_build_object('supplier_id', p_supplier_id));
  return jsonb_build_object('note_id', v_id);
end $$;

-- ===========================================================================
-- Categories
-- ===========================================================================
create or replace function public.rpc_upsert_category(
  p_name        text,
  p_category_id uuid default null,
  p_description text default null,
  p_image_url   text default null,
  p_sort_order  int default 0,
  p_active      boolean default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id   uuid;
  v_slug text;
begin
  perform public.fn_require_owner();

  v_slug := lower(regexp_replace(btrim(p_name), '[^a-zA-Z0-9]+', '-', 'g'));
  v_slug := btrim(v_slug, '-');

  if p_category_id is null then
    insert into public.categories (name, slug, description, image_url, sort_order)
    values (btrim(p_name), v_slug, p_description, p_image_url, coalesce(p_sort_order, 0))
    returning id into v_id;
  else
    update public.categories
       set name = btrim(p_name), slug = v_slug,
           description = coalesce(p_description, description),
           image_url = coalesce(p_image_url, image_url),
           sort_order = coalesce(p_sort_order, sort_order),
           active = coalesce(p_active, active)
     where id = p_category_id
    returning id into v_id;
    if not found then
      raise exception 'CATEGORY_NOT_FOUND: no category with id %', p_category_id using errcode = '23503';
    end if;
  end if;

  perform public.fn_audit('CATEGORY_UPSERT', 'categories', v_id, null,
    jsonb_build_object('name', p_name, 'slug', v_slug));
  return jsonb_build_object('category_id', v_id, 'slug', v_slug);
end $$;

-- ===========================================================================
-- Settings (owner-only writes; everything is audit-logged)
-- ===========================================================================
create or replace function public.rpc_update_settings(p_settings jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user public.app_users;
  k text;
  v jsonb;
  v_public boolean;
begin
  v_user := public.fn_current_user_row();
  perform public.fn_require_owner();

  if p_settings is null or jsonb_typeof(p_settings) <> 'object' then
    raise exception 'INVALID_SETTINGS: expected a JSON object of key/value pairs' using errcode = '22023';
  end if;

  for k, v in select * from jsonb_each(p_settings) loop
    v_public := k in ('shop_name','shop_tagline','currency','whatsapp_number',
                      'whatsapp_display','telegram_username','telegram_bot_username',
                      'support_hours','expiry_warning_days','low_stock_band','tithe_rate',
                      'address','phone','email','instagram','tiktok','telegram_order_destination');

    -- Bot tokens and other secrets must never be public rows.
    if k in ('telegram_bot_token','supabase_service_key','backup_location') then
      v_public := false;
    end if;

    insert into public.settings (key, value, is_public, updated_by)
    values (k, v, v_public, v_user.id)
    on conflict (key) do update
      set value = excluded.value, is_public = excluded.is_public,
          updated_by = excluded.updated_by, updated_at = now();

    -- Values of secret keys are masked in the audit trail.
    perform public.fn_audit('SETTINGS_UPDATE', 'settings', null, null,
      jsonb_build_object('key', k,
        'value', case when k in ('telegram_bot_token','supabase_service_key') then '***redacted***' else v end,
        'is_public', v_public));
  end loop;

  return jsonb_build_object('updated', (select count(*) from jsonb_object_keys(p_settings)),
                            'settings', public.fn_public_settings());
end $$;

create or replace function public.rpc_settings_for_admin()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select case when public.fn_is_owner()
    then coalesce((select jsonb_object_agg(s.key, jsonb_build_object('value',
      case when s.key in ('telegram_bot_token') then to_jsonb('***set***'::text) else s.value end,
      'is_public', s.is_public, 'description', s.description)) from public.settings s), '{}'::jsonb)
    else '{}'::jsonb end;
$$;

-- ===========================================================================
-- Audit log browsing (owner-only; the table itself is immutable)
-- ===========================================================================
create or replace function public.rpc_audit_log(
  p_action      text default null,
  p_entity_type text default null,
  p_from        timestamptz default null,
  p_to          timestamptz default null,
  p_limit       int default 100,
  p_offset      int default 0
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
  v_total int;
begin
  perform public.fn_require_owner();

  select count(*) into v_total from public.audit_logs a
  where (p_action is null or a.action = p_action)
    and (p_entity_type is null or a.entity_type = p_entity_type)
    and (p_from is null or a.created_at >= p_from)
    and (p_to is null or a.created_at <= p_to);

  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb) into v_items
  from (
    select a.id, a.user_id, a.actor_email, a.action, a.entity_type, a.entity_id,
           a.old_value, a.new_value, a.note, a.created_at
    from public.audit_logs a
    where (p_action is null or a.action = p_action)
      and (p_entity_type is null or a.entity_type = p_entity_type)
      and (p_from is null or a.created_at >= p_from)
      and (p_to is null or a.created_at <= p_to)
    order by a.created_at desc
    limit greatest(coalesce(p_limit, 100), 1) offset greatest(coalesce(p_offset, 0), 0)
  ) t;

  return jsonb_build_object('items', v_items, 'count', v_total);
end $$;

create or replace function public.rpc_audit_actions()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select case when public.fn_is_owner()
    then coalesce((select jsonb_agg(x.a) from (select distinct action as a from public.audit_logs order by a) x), '[]'::jsonb)
    else '[]'::jsonb end;
$$;

-- ===========================================================================
-- Backup status (spec §58). Runs are recorded by the scheduled job; the owner
-- sees the result in Settings.
-- ===========================================================================
create or replace function public.rpc_backup_status()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select case when public.fn_is_owner() then jsonb_build_object(
    'last_run', (select to_jsonb(t) from (
        select status, backup_type, started_at, finished_at, size_bytes, table_count,
               row_count, storage_files, location, notes
        from public.backup_runs order by started_at desc limit 1) t),
    'next_scheduled', (select case when max(started_at) is null then now() + interval '7 days'
                                   else max(started_at) + interval '7 days' end
                       from public.backup_runs),
    'history', coalesce((select jsonb_agg(to_jsonb(h) order by h.started_at desc) from (
        select status, started_at, finished_at, size_bytes, row_count
        from public.backup_runs order by started_at desc limit 8) h), '[]'::jsonb),
    'schedule', 'Weekly, automatic',
    'covers', jsonb_build_array('PostgreSQL data', 'Database recovery', 'Product images (Storage)', 'Configuration settings')
  ) else '{}'::jsonb end;
$$;

create or replace function public.rpc_record_backup_run(
  p_status text, p_size_bytes bigint default null, p_table_count int default null,
  p_row_count bigint default null, p_storage_files int default null,
  p_location text default null, p_notes text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  perform public.fn_require_owner();
  insert into public.backup_runs (status, finished_at, size_bytes, table_count, row_count,
                                  storage_files, location, notes)
  values (p_status, now(), p_size_bytes, p_table_count, p_row_count, p_storage_files, p_location, p_notes)
  returning id into v_id;
  return jsonb_build_object('backup_id', v_id, 'status', p_status);
end $$;

-- ===========================================================================
-- Profile self-service (any signed-in user, including suppliers)
-- ===========================================================================
create or replace function public.rpc_update_my_profile(
  p_full_name text default null,
  p_phone     text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid := auth.uid();
begin
  if v_id is null then
    raise exception 'NOT_SIGNED_IN: sign in first' using errcode = '42501';
  end if;

  update public.app_users
     set full_name = coalesce(p_full_name, full_name),
         phone = coalesce(p_phone, phone),
         last_login_at = now()
   where id = v_id;

  if not found then
    raise exception 'PROFILE_NOT_FOUND: no profile is linked to this login' using errcode = '23503';
  end if;

  return jsonb_build_object('user_id', v_id, 'updated', true);
end $$;

-- ----------------------------------------------------------------------------
-- >>> 0016_rpcs_reports.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0016 — Dashboards & reports
-- ============================================================================
-- Every figure here is aggregate-only, so the JSON that reaches a browser
-- contains summaries rather than the underlying cost records. Role separation
-- is enforced twice: the function refuses the wrong caller, and the tables it
-- reads are themselves owner-only under RLS.
-- ============================================================================

-- ===========================================================================
-- Owner dashboard (spec §43)
-- ===========================================================================
create or replace function public.rpc_owner_dashboard(
  p_date date default current_date
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_week_start date := date_trunc('week', p_date)::date;
  v_month_start date := date_trunc('month', p_date)::date;
  r jsonb;
  v_day   record; v_week record; v_month record;
  v_stock record;
  v_alerts jsonb := '[]'::jsonb;
  v_top jsonb;
  v_trend jsonb;
  v_staff jsonb;
  v_requests jsonb;
  v_demand jsonb;
  v_supplier_outstanding numeric;
  v_pnl record;
  v_warn_days int := coalesce((public.fn_setting('expiry_warning_days', '30'::jsonb))::text::int, 30);
begin
  perform public.fn_require_owner();

  select * into v_pnl from public.v_pnl_monthly where period_month = v_month_start;

  select public.fn_money(coalesce(sum(total_amount - returned_amount), 0)) as net,
         count(*) as sales_count,
         public.fn_money(coalesce(sum(total_amount - returned_amount - cogs_amount), 0)) as gross,
         public.fn_money(coalesce(sum(total_amount - returned_amount) * 0.03, 0)) as commission_estimate
    into v_day from public.sales
   where sale_date = p_date and status <> 'VOIDED';

  select public.fn_money(coalesce(sum(total_amount - returned_amount), 0)) as net, count(*) as sales_count
    into v_week from public.sales
   where sale_date between v_week_start and p_date and status <> 'VOIDED';

  select public.fn_money(coalesce(sum(total_amount - returned_amount), 0)) as net, count(*) as sales_count
    into v_month from public.sales
   where sale_date between v_month_start and p_date and status <> 'VOIDED';

  select
    coalesce(sum(public.fn_on_hand(p.id)), 0) as stock_units,
    public.fn_money(coalesce(sum(public.fn_on_hand(p.id) * public.fn_avg_unit_cost(p.id)), 0)) as stock_value,
    count(*) filter (where public.fn_on_hand(p.id) > 0 and public.fn_on_hand(p.id) <= p.minimum_stock) as low_stock,
    count(*) filter (where public.fn_on_hand(p.id) <= 0) as out_of_stock,
    count(*) filter (where p.expiry_date is not null and p.expiry_date < p_date) as expired,
    count(*) filter (where p.expiry_date is not null and p.expiry_date >= p_date
                       and p.expiry_date <= p_date + v_warn_days) as expiring_soon
    into v_stock from public.products p where p.active;

  select coalesce(sum(outstanding), 0) into v_supplier_outstanding from public.supplier_payables;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.revenue desc), '[]'::jsonb) into v_top from (
    select p.name, p.product_code, sum(si.quantity) as units,
           public.fn_money(sum(si.line_total)) as revenue,
           public.fn_money(sum(si.line_cogs)) as cogs
    from public.sale_items si
    join public.sales sa on sa.id = si.sale_id
    join public.products p on p.id = si.product_id
    where sa.status <> 'VOIDED' and sa.sale_date >= v_month_start
    group by p.id, p.name, p.product_code
    order by sum(si.line_total) desc limit 5) t;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.d), '[]'::jsonb) into v_trend from (
    select d::date as d,
           public.fn_money(coalesce((select sum(total_amount - returned_amount) from public.sales s
              where s.sale_date = d::date and s.status <> 'VOIDED'), 0)) as revenue
    from generate_series(p_date - 13, p_date, interval '1 day') d) t;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.revenue desc), '[]'::jsonb) into v_staff from (
    select u.full_name, u.id as staff_id,
           count(sa.id) as sales_count,
           public.fn_money(coalesce(sum(sa.total_amount - sa.returned_amount), 0)) as revenue,
           public.fn_money(coalesce((select sum(c.amount) from public.commissions c
              where c.staff_id = u.id and c.sale_date between v_month_start and p_date), 0)) as commission
    from public.app_users u
    left join public.sales sa on sa.staff_id = u.id and sa.sale_date between v_month_start and p_date
                              and sa.status <> 'VOIDED'
    where u.role = 'STAFF' and u.active
    group by u.id, u.full_name) t;

  select jsonb_build_object(
      'new', count(*) filter (where status = 'NEW'),
      'open', count(*) filter (where status not in ('FULFILLED','CANCELLED')),
      'total', count(*),
      'recent', coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc) filter (where t.rn <= 5), '[]'::jsonb))
    into v_requests from (
      select cr.id, cr.request_number, cr.customer_name, cr.customer_phone,
             cr.requested_product_name, cr.quantity, cr.status, cr.source,
             cr.was_unavailable, cr.created_at,
             row_number() over (order by cr.created_at desc) rn
      from public.customer_requests cr) t;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.request_count desc), '[]'::jsonb) into v_demand from (
    select coalesce(p.name, cr.requested_product_name) as product_name,
           cr.product_id,
           count(*) as request_count,
           count(distinct cr.customer_phone) as unique_customers,
           max(cr.created_at) as last_requested,
           public.fn_on_hand(cr.product_id) as quantity_on_hand,
           coalesce(public.fn_availability(public.fn_on_hand(cr.product_id),
                    (select minimum_stock from public.products where id = cr.product_id)), 'OUT') as availability,
           bool_or(cr.was_unavailable) as unavailable_request
    from public.customer_requests cr
    left join public.products p on p.id = cr.product_id
    where cr.status <> 'CANCELLED' and cr.created_at >= v_month_start - interval '90 days'
    group by cr.product_id, coalesce(p.name, cr.requested_product_name)
    limit 8) t;

  -- Alerts (spec §43)
  select coalesce(jsonb_agg(a order by a ->> 'severity', a ->> 'title'), '[]'::jsonb) into v_alerts from (
    select jsonb_build_object('severity','warning','type','LOW_STOCK','title', p.name,
             'detail', format('%s left — at or below the minimum of %s', public.fn_on_hand(p.id), p.minimum_stock),
             'product_id', p.id) a
    from public.products p
    where p.active and public.fn_on_hand(p.id) > 0 and public.fn_on_hand(p.id) <= p.minimum_stock
    union all
    select jsonb_build_object('severity','danger','type','OUT_OF_STOCK','title', p.name,
             'detail','Out of stock', 'product_id', p.id)
    from public.products p where p.active and public.fn_on_hand(p.id) <= 0
    union all
    select jsonb_build_object('severity','danger','type','EXPIRED','title', p.name,
             'detail', format('Expired on %s — cannot be sold', to_char(p.expiry_date,'DD Mon YYYY')),
             'product_id', p.id)
    from public.products p where p.active and p.expiry_date is not null and p.expiry_date < p_date
    union all
    select jsonb_build_object('severity','warning','type','EXPIRING','title', p.name,
             'detail', format('Expires %s', to_char(p.expiry_date,'DD Mon YYYY')), 'product_id', p.id)
    from public.products p
    where p.active and p.expiry_date is not null and p.expiry_date >= p_date
      and p.expiry_date <= p_date + v_warn_days
    union all
    select jsonb_build_object('severity','info','type','COST_PENDING','title', p.name,
             'detail', 'Received without a purchase cost — record it so payables are final',
             'product_id', p.id, 'batch_id', b.id)
    from public.purchase_batches b join public.products p on p.id = b.product_id
    where b.cost_status = 'PENDING'
    union all
    select jsonb_build_object('severity','info','type','DEMAND','title',
             coalesce(p.name, cr.requested_product_name),
             'detail', format('%s customer(s) requested this and it is unavailable',
                              count(distinct cr.customer_phone)),
             'product_id', cr.product_id)
    from public.customer_requests cr
    left join public.products p on p.id = cr.product_id
    where cr.was_unavailable and cr.status not in ('CANCELLED','FULFILLED')
    group by cr.product_id, coalesce(p.name, cr.requested_product_name)
  ) x;

  return jsonb_build_object(
    'today', jsonb_build_object('sales', v_day.net, 'transactions', v_day.sales_count,
                                'gross_profit', v_day.gross),
    'week', jsonb_build_object('sales', v_week.net, 'transactions', v_week.sales_count),
    'month', jsonb_build_object('sales', v_month.net, 'transactions', v_month.sales_count,
                                'net_sales', coalesce(v_pnl.net_sales, 0),
                                'cogs', coalesce(v_pnl.cogs, 0),
                                'gross_profit', coalesce(v_pnl.gross_profit, 0),
                                'expenses', coalesce(v_pnl.operating_expenses, 0),
                                'commission', coalesce(v_pnl.staff_commission, 0),
                                'net_profit', coalesce(v_pnl.net_profit, 0),
                                'tithe_due', coalesce(v_pnl.tithe_due_10pct, 0)),
    'supplier_payable', public.fn_money(coalesce(v_supplier_outstanding, 0)),
    'stock', jsonb_build_object('units', v_stock.stock_units, 'value', v_stock.stock_value,
                                'low_stock', v_stock.low_stock, 'out_of_stock', v_stock.out_of_stock,
                                'expired', v_stock.expired, 'expiring_soon', v_stock.expiring_soon),
    'top_products', coalesce(v_top, '[]'::jsonb),
    'sales_trend', coalesce(v_trend, '[]'::jsonb),
    'staff_performance', coalesce(v_staff, '[]'::jsonb),
    'customer_requests', coalesce(v_requests, '{}'::jsonb),
    'customer_demand', coalesce(v_demand, '[]'::jsonb),
    'alerts', coalesce(v_alerts, '[]'::jsonb)
  );
end $$;

-- ===========================================================================
-- Staff dashboard (spec §44) — operational only. No profit, COGS, payable,
-- purchase cost, stock value, expenses or other staff members' figures.
-- ===========================================================================
create or replace function public.rpc_staff_dashboard(p_date date default current_date)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
  v_month_start date := date_trunc('month', p_date)::date;
  v_today record;
  v_mine record;
  v_stock record;
  v_pending int;
begin
  if not public.fn_is_internal() then
    raise exception 'INTERNAL_ONLY: this dashboard is for LuBella staff' using errcode = '42501';
  end if;

  select public.fn_money(coalesce(sum(total_amount - returned_amount), 0)) as amount, count(*) as txns
    into v_today from public.sales
   where sale_date = p_date and status <> 'VOIDED';

  select public.fn_money(coalesce(sum(total_amount - returned_amount), 0)) as amount, count(*) as txns
    into v_mine from public.sales
   where staff_id = v_uid and sale_date = p_date and status <> 'VOIDED';

  select
    count(*) filter (where public.fn_on_hand(p.id) > 0) as available,
    count(*) filter (where public.fn_on_hand(p.id) > 0 and public.fn_on_hand(p.id) <= p.minimum_stock) as low,
    count(*) filter (where public.fn_on_hand(p.id) <= 0) as out
    into v_stock from public.products p where p.active;

  select count(*) into v_pending from public.restocks where cost_pending;

  return jsonb_build_object(
    'today_sales', jsonb_build_object('amount', v_today.amount, 'transactions', v_today.txns),
    'my_sales_today', jsonb_build_object('amount', v_mine.amount, 'transactions', v_mine.txns),
    'my_sales_month', jsonb_build_object(
        'amount', (select public.fn_money(coalesce(sum(total_amount - returned_amount), 0))
                   from public.sales where staff_id = v_uid and sale_date >= v_month_start and status <> 'VOIDED'),
        'transactions', (select count(*) from public.sales
                   where staff_id = v_uid and sale_date >= v_month_start and status <> 'VOIDED')),
    'my_commission_month', (select public.fn_money(coalesce(sum(amount), 0)) from public.commissions
                            where staff_id = v_uid and sale_date >= v_month_start),
    'products', jsonb_build_object('available', v_stock.available, 'low_stock', v_stock.low,
                                   'out_of_stock', v_stock.out),
    'pending_restocks', coalesce(v_pending, 0),
    'recent_sales', coalesce((select jsonb_agg(to_jsonb(t)) from (
        select sale_number, sale_date, total_amount, discount_amount, payment_method, status
        from public.sales where staff_id = v_uid and status <> 'VOIDED'
        order by created_at desc limit 8) t), '[]'::jsonb)
  );
end $$;

-- ===========================================================================
-- Reports (spec §55)
-- ===========================================================================
create or replace function public.rpc_report_sales(
  p_from date default current_date, p_to date default current_date,
  p_staff_id uuid default null, p_payment_method public.payment_method default null
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
  v_totals record;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb) into v_items from (
    select sa.id, sa.sale_number, sa.sale_date, sa.created_at, u.full_name as staff_name,
           sa.subtotal, sa.discount_amount, sa.total_amount, sa.returned_amount,
           public.fn_money(sa.total_amount - sa.returned_amount) as net_amount,
           sa.cogs_amount, sa.gross_profit, sa.payment_method, sa.status,
           (select count(*) from public.sale_items si where si.sale_id = sa.id) as line_count
    from public.sales sa
    join public.app_users u on u.id = sa.staff_id
    where sa.sale_date between p_from and p_to
      and (p_staff_id is null or sa.staff_id = p_staff_id)
      and (p_payment_method is null or sa.payment_method = p_payment_method)
    order by sa.created_at desc) t;

  select public.fn_money(coalesce(sum(subtotal), 0)) as gross_sales,
         public.fn_money(coalesce(sum(discount_amount), 0)) as discounts,
         public.fn_money(coalesce(sum(returned_amount), 0)) as returns,
         public.fn_money(coalesce(sum(total_amount - returned_amount), 0)) as net_sales,
         public.fn_money(coalesce(sum(cogs_amount), 0)) as cogs,
         public.fn_money(coalesce(sum(total_amount - returned_amount - cogs_amount), 0)) as gross_profit,
         count(*) as sale_count
    into v_totals from public.sales
   where sale_date between p_from and p_to and status <> 'VOIDED'
     and (p_staff_id is null or staff_id = p_staff_id)
     and (p_payment_method is null or payment_method = p_payment_method);

  return jsonb_build_object('from', p_from, 'to', p_to, 'totals', to_jsonb(v_totals), 'items', v_items);
end $$;

create or replace function public.rpc_report_product_sales(
  p_from date default current_date, p_to date default current_date
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
  v_costed jsonb;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.revenue desc), '[]'::jsonb) into v_items from (
    select p.name, p.product_code, c.name as category,
           sum(si.quantity) as units_sold,
           public.fn_money(sum(si.line_subtotal)) as gross_revenue,
           public.fn_money(sum(si.line_discount)) as discounts,
           public.fn_money(sum(si.line_total)) as net_revenue,
           public.fn_money(sum(si.line_cogs)) as cogs,
           public.fn_money(sum(si.line_total - si.line_cogs)) as gross_profit,
           sum(si.returned_qty) as units_returned
    from public.sale_items si
    join public.sales sa on sa.id = si.sale_id
    join public.products p on p.id = si.product_id
    left join public.categories c on c.id = p.category_id
    where sa.sale_date between p_from and p_to and sa.status <> 'VOIDED'
    group by p.id, p.name, p.product_code, c.name) t;

  -- Product performance against what customers asked for — the buying insight.
  select coalesce(jsonb_agg(to_jsonb(t) order by t.requests desc), '[]'::jsonb) into v_costed from (
    select coalesce(p.name, cr.requested_product_name) as product_name,
           count(*) as requests, count(distinct cr.customer_phone) as customers,
           max(cr.created_at) as last_requested
    from public.customer_requests cr left join public.products p on p.id = cr.product_id
    where cr.created_at::date between p_from and p_to
    group by cr.product_id, coalesce(p.name, cr.requested_product_name)) t;

  return jsonb_build_object('from', p_from, 'to', p_to, 'products', v_items, 'demand', v_costed);
end $$;

create or replace function public.rpc_report_inventory(
  p_category_id uuid default null, p_only_attention boolean default false
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
  v_totals record;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.stock_value desc, t.name), '[]'::jsonb) into v_items
  from (
    select v.product_code, v.name, v.category_name, v.supplier_name, v.quantity_on_hand,
           v.avg_unit_cost, v.stock_value, v.selling_price, v.unit_margin, v.availability,
           v.expiry_status, v.expiry_date, v.minimum_stock
    from public.v_owner_inventory v
    where (p_category_id is null or v.category_name = (select name from public.categories where id = p_category_id))
      and (not p_only_attention or v.availability <> 'AVAILABLE' or v.expiry_status in ('EXPIRED','EXPIRING_SOON'))
  ) t;

  select public.fn_money(sum(stock_value)) as total_value,
         sum(quantity_on_hand) as total_units,
         count(*) as sku_count,
         public.fn_money(sum(quantity_on_hand * selling_price)) as retail_value
    into v_totals from public.v_owner_inventory;

  return jsonb_build_object('items', v_items, 'totals', to_jsonb(v_totals));
end $$;

create or replace function public.rpc_report_stock_movements(
  p_from date default current_date, p_to date default current_date,
  p_product_id uuid default null, p_movement_type public.movement_type default null
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
  v_summary jsonb;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb) into v_items from (
    select sm.created_at, sm.movement_type, sm.quantity, sm.reason,
           p.name as product_name, p.product_code, u.full_name as created_by_name,
           sm.reference_type, sm.reference_id, sm.unit_cost
    from public.stock_movements sm
    join public.products p on p.id = sm.product_id
    left join public.app_users u on u.id = sm.created_by
    where sm.created_at::date between p_from and p_to
      and (p_product_id is null or sm.product_id = p_product_id)
      and (p_movement_type is null or sm.movement_type = p_movement_type)
    limit 500) t;

  select coalesce(jsonb_object_agg(movement_type, qty), '{}'::jsonb) into v_summary from (
    select sm.movement_type::text as movement_type, sum(sm.quantity) as qty
    from public.stock_movements sm
    where sm.created_at::date between p_from and p_to
      and (p_product_id is null or sm.product_id = p_product_id)
    group by 1) x;

  return jsonb_build_object('from', p_from, 'to', p_to, 'items', v_items, 'summary', v_summary);
end $$;

create or replace function public.rpc_report_fifo_cogs(
  p_from date default current_date, p_to date default current_date
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
  v_totals record;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb) into v_items from (
    select fa.created_at, p.name as product_name, s.name as supplier_name,
           b.batch_number, b.received_date, sa.sale_number,
           fa.quantity, fa.unit_cost, fa.total_cost, fa.direction,
           case when fa.quantity > 0 then public.fn_money(fa.total_cost / fa.quantity) else 0 end as effective_unit_cost
    from public.fifo_allocations fa
    join public.purchase_batches b on b.id = fa.batch_id
    join public.products p on p.id = fa.product_id
    join public.suppliers s on s.id = fa.supplier_id
    left join public.sales sa on sa.id = fa.sale_id
    where fa.created_at::date between p_from and p_to
    limit 500) t;

  select public.fn_money(coalesce(sum(total_cost) filter (where direction = 'OUT'), 0)) as cogs_out,
         public.fn_money(coalesce(sum(total_cost) filter (where direction = 'IN'), 0)) as reversed_in,
         count(*) as allocations
    into v_totals from public.fifo_allocations
   where created_at::date between p_from and p_to;

  return jsonb_build_object('from', p_from, 'to', p_to, 'items', v_items, 'totals', to_jsonb(v_totals));
end $$;

create or replace function public.rpc_report_supplier_payable(
  p_supplier_id uuid default null
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_suppliers jsonb;
  v_lines jsonb;
  v_totals record;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.outstanding desc), '[]'::jsonb) into v_suppliers from (
    select supplier_code, name, total_payable, total_paid, outstanding, open_lines, last_activity
    from public.v_owner_supplier_balance
    where p_supplier_id is null or supplier_id = p_supplier_id) t;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.entry_date desc), '[]'::jsonb) into v_lines from (
    select sp.entry_date, s.name as supplier_name, p.name as product_name, b.batch_number,
           sp.quantity_sold, sp.purchase_cost, sp.payable_amount, sp.amount_paid, sp.outstanding,
           sp.status, sp.is_reversal
    from public.supplier_payables sp
    join public.suppliers s on s.id = sp.supplier_id
    join public.products p on p.id = sp.product_id
    join public.purchase_batches b on b.id = sp.purchase_batch_id
    where p_supplier_id is null or sp.supplier_id = p_supplier_id
    order by sp.entry_date desc limit 300) t;

  select public.fn_money(coalesce(sum(payable_amount), 0)) as payable,
         public.fn_money(coalesce(sum(amount_paid), 0)) as paid,
         public.fn_money(coalesce(sum(outstanding), 0)) as outstanding
    into v_totals from public.supplier_payables
   where p_supplier_id is null or supplier_id = p_supplier_id;

  return jsonb_build_object('suppliers', v_suppliers, 'lines', v_lines, 'totals', to_jsonb(v_totals));
end $$;

create or replace function public.rpc_report_expenses(
  p_from date default date_trunc('month', current_date)::date,
  p_to   date default current_date
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
  v_by_category jsonb;
  v_total numeric;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.expense_date desc), '[]'::jsonb) into v_items from (
    select e.expense_number, e.expense_date, e.category, e.amount, e.payment_method,
           e.description, e.receipt_url, u.full_name as created_by_name
    from public.expenses e left join public.app_users u on u.id = e.created_by
    where e.expense_date between p_from and p_to
    order by e.expense_date desc) t;

  select coalesce(jsonb_agg(to_jsonb(c) order by c.total desc), '[]'::jsonb) into v_by_category from (
    select category, public.fn_money(sum(amount)) as total, count(*) as entries
    from public.expenses where expense_date between p_from and p_to
    group by category) c;

  select public.fn_money(coalesce(sum(amount), 0)) into v_total
  from public.expenses where expense_date between p_from and p_to;

  return jsonb_build_object('from', p_from, 'to', p_to, 'items', v_items,
                            'by_category', v_by_category, 'total', v_total);
end $$;

create or replace function public.rpc_report_pnl(
  p_from date default (date_trunc('month', current_date) - interval '5 months')::date,
  p_to   date default current_date
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_months jsonb;
  v_supplier_payments numeric;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.period_month desc), '[]'::jsonb) into v_months
  from (
    select period_month, gross_sales, discounts, returns, net_sales, cogs, gross_profit,
           operating_expenses, staff_commission, net_profit, tithe_due_10pct
    from public.v_pnl_monthly
    where period_month between date_trunc('month', p_from)::date and date_trunc('month', p_to)::date) t;

  -- Shown for transparency: supplier payments are a balance-sheet settlement.
  select public.fn_money(coalesce(sum(amount), 0)) into v_supplier_payments
  from public.supplier_payments
  where payment_date between p_from and p_to and voided_at is null;

  return jsonb_build_object(
    'from', p_from, 'to', p_to, 'months', v_months,
    'formula', jsonb_build_object(
      'net_sales', 'Sales − Discounts − Returns',
      'gross_profit', 'Net Sales − COGS',
      'net_profit', 'Gross Profit − Operating Expenses − Staff Commission'),
    'supplier_payments_in_period', v_supplier_payments,
    'supplier_payments_note', 'Supplier payments settle a liability already recognised in COGS. They are NOT an operating expense and are excluded from net profit.'
  );
end $$;

create or replace function public.rpc_report_commission(
  p_from date default date_trunc('month', current_date)::date,
  p_to   date default current_date,
  p_staff_id uuid default null
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_staff jsonb;
  v_lines jsonb;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.net_commission desc), '[]'::jsonb) into v_staff from (
    select u.id as staff_id, u.full_name, u.commission_rate,
           public.fn_money(coalesce(sum(c.amount) filter (where c.type = 'EARNED'), 0)) as earned,
           public.fn_money(coalesce(sum(c.amount) filter (where c.type in ('RETURN_REVERSAL','VOID_REVERSAL')), 0)) as reversals,
           public.fn_money(coalesce(sum(c.amount), 0)) as net_commission,
           public.fn_money(coalesce((select sum(cp.amount) from public.commission_payments cp
              where cp.staff_id = u.id), 0)) as paid,
           public.fn_money(coalesce(sum(c.amount), 0) -
             coalesce((select sum(cp.amount) from public.commission_payments cp where cp.staff_id = u.id), 0)) as outstanding
    from public.app_users u
    left join public.commissions c on c.staff_id = u.id and c.sale_date between p_from and p_to
    where u.role in ('STAFF','OWNER') and (p_staff_id is null or u.id = p_staff_id)
    group by u.id, u.full_name, u.commission_rate) t;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.sale_date desc), '[]'::jsonb) into v_lines from (
    select c.sale_date, u.full_name as staff_name, c.type, c.amount, c.rate,
           sa.sale_number, sa.total_amount, sa.discount_amount, c.note
    from public.commissions c
    left join public.app_users u on u.id = c.staff_id
    left join public.sales sa on sa.id = c.sale_id
    where c.sale_date between p_from and p_to and (p_staff_id is null or c.staff_id = p_staff_id)
    order by c.created_at desc limit 300) t;

  return jsonb_build_object('from', p_from, 'to', p_to, 'staff', v_staff, 'lines', v_lines);
end $$;

create or replace function public.rpc_report_returns(
  p_from date default date_trunc('month', current_date)::date,
  p_to   date default current_date
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_returns jsonb;
  v_voids jsonb;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb) into v_returns from (
    select r.return_number, r.return_date, sa.sale_number, sa.status as sale_status,
           r.return_type, r.return_amount, r.cogs_reversed, r.restock_decision, r.reason,
           u.full_name as processed_by_name,
           (select count(*) from public.return_items ri where ri.return_id = r.id) as line_count
    from public.returns r
    join public.sales sa on sa.id = r.sale_id
    left join public.app_users u on u.id = r.processed_by
    where r.return_date between p_from and p_to) t;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.voided_at desc), '[]'::jsonb) into v_voids from (
    select sa.sale_number, sa.sale_date, sa.total_amount, sa.void_reason, sa.voided_at,
           u.full_name as voided_by_name
    from public.sales sa left join public.app_users u on u.id = sa.voided_by
    where sa.status = 'VOIDED' and sa.sale_date between p_from and p_to) t;

  return jsonb_build_object(
    'returns', v_returns, 'voids', v_voids,
    'note', 'Returns on a voided sale are shown in the void, not counted twice in the P&L.');
end $$;

create or replace function public.rpc_report_tithe(p_year int default extract(year from current_date)::int)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.period_month desc), '[]'::jsonb) into v_items from (
    select p.period_month,
           coalesce(p.net_profit, 0) as net_profit,
           coalesce((select tr.tithe_rate from public.tithe_records tr where tr.period_month = p.period_month), 0.10) as tithe_rate,
           coalesce((select tr.tithe_amount from public.tithe_records tr where tr.period_month = p.period_month),
                    case when p.net_profit > 0 then public.fn_money(p.net_profit * 0.10) else 0 end) as tithe_amount,
           coalesce((select tr.status from public.tithe_records tr where tr.period_month = p.period_month), 'DUE') as status,
           (select tr.paid_date from public.tithe_records tr where tr.period_month = p.period_month) as paid_date,
           (select tr.payment_method from public.tithe_records tr where tr.period_month = p.period_month) as payment_method,
           (select tr.reference from public.tithe_records tr where tr.period_month = p.period_month) as reference
    from public.v_pnl_monthly p
    where extract(year from p.period_month) = p_year) t;

  return jsonb_build_object('year', p_year, 'months', v_items,
    'note', 'Tithe is 10% of net profit, paid monthly. A loss produces no tithe, and tithe is not an operating expense.');
end $$;

create or replace function public.rpc_report_customer_demand(
  p_days int default 90, p_only_unavailable boolean default false
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
begin
  perform public.fn_require_internal();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.request_count desc), '[]'::jsonb) into v_items from (
    select coalesce(p.name, cr.requested_product_name) as product_name,
           cr.product_id,
           c.name as category,
           count(*) as request_count,
           count(distinct cr.customer_phone) as unique_customers,
           max(cr.created_at) as last_requested,
           min(cr.created_at) as first_requested,
           public.fn_on_hand(cr.product_id) as quantity_on_hand,
           public.fn_availability(public.fn_on_hand(cr.product_id), p.minimum_stock) as availability,
           coalesce(p.minimum_stock, 0) as minimum_stock,
           bool_or(cr.was_unavailable) as unavailable_request,
           format('%s customer%s %s requested this product.',
                  count(distinct cr.customer_phone),
                  case when count(distinct cr.customer_phone) = 1 then '' else 's' end,
                  case when count(distinct cr.customer_phone) = 1 then 'has' else 'have' end) as demand_message
    from public.customer_requests cr
    left join public.products p on p.id = cr.product_id
    left join public.categories c on c.id = coalesce(cr.category_id, p.category_id)
    where cr.status <> 'CANCELLED'
      and cr.created_at >= now() - make_interval(days => greatest(p_days, 1))
    group by cr.product_id, coalesce(p.name, cr.requested_product_name), c.name, p.minimum_stock) t;

  if p_only_unavailable then
    select coalesce(jsonb_agg(x), '[]'::jsonb) into v_items
    from jsonb_array_elements(v_items) x
    where (x ->> 'availability') <> 'AVAILABLE';
  end if;

  return jsonb_build_object('days', p_days, 'items', coalesce(v_items, '[]'::jsonb));
end $$;

create or replace function public.rpc_report_customer_requests(
  p_from date default (current_date - 30),
  p_to   date default current_date,
  p_status public.request_status default null,
  p_source public.request_source default null,
  p_product_id uuid default null
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
  v_stats record;
begin
  perform public.fn_require_internal();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb) into v_items from (
    select cr.request_number as "requestNumber", cr.customer_name as "customerName",
           cr.customer_phone as "customerPhone", cr.requested_product_name as "product",
           cr.quantity, cr.status, cr.source, cr.was_unavailable, cr.created_at, cr.updated_at,
           p.name as matched_product, cr.owner_note, cr.message
    from public.customer_requests cr
    left join public.products p on p.id = cr.product_id
    where cr.created_at::date between p_from and p_to
      and (p_status is null or cr.status = p_status)
      and (p_source is null or cr.source = p_source)
      and (p_product_id is null or cr.product_id = p_product_id)
    order by cr.created_at desc limit 500) t;

  select count(*) as total,
         count(*) filter (where status = 'NEW') as new_count,
         count(*) filter (where status in ('FULFILLED')) as fulfilled,
         count(distinct customer_phone) as customers,
         count(*) filter (where was_unavailable) as unavailable
    into v_stats from public.customer_requests
   where created_at::date between p_from and p_to;

  return jsonb_build_object('from', p_from, 'to', p_to, 'items', v_items, 'stats', to_jsonb(v_stats));
end $$;


-- ===========================================================================
-- Purchase batches & receivings (owner-only)
-- ---------------------------------------------------------------------------
-- These tables carry purchase cost, so they are not granted to any client role
-- at all; the owner reaches them here. The same rows also drive the "record the
-- real cost" workflow after a staff shipment arrives unpriced, and the
-- «N customers have requested this product» prompt at purchasing time.
-- ===========================================================================
create or replace function public.rpc_list_batches(
  p_product_id        uuid default null,
  p_supplier_id       uuid default null,
  p_only_pending_cost boolean default false,
  p_limit             int default 200
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.received_date desc, t.created_at desc), '[]'::jsonb)
    into v_items
  from (
    select b.id, b.batch_number, b.received_date, b.created_at, b.expiry_date,
           p.name as product_name, p.product_code, p.selling_price,
           s.name as supplier_name, s.id as supplier_id,
           b.unit_cost, b.cost_status, b.quantity_received, b.quantity_remaining,
           b.quantity_sold, b.status as batch_status,
           public.fn_money(b.quantity_sold * b.unit_cost) as cost_of_units_sold,
           public.fn_money(b.quantity_remaining * b.unit_cost) as value_remaining,
           case when b.unit_cost > 0
                then public.fn_money(p.selling_price - b.unit_cost) end as unit_margin,
           b.notes,
           -- demand signal, so purchasing decisions are informed (spec §13)
           (select count(*) from public.customer_requests cr
             where cr.product_id = b.product_id and cr.status <> 'CANCELLED') as request_count,
           (select count(*) from public.customer_requests cr
             where cr.product_id = b.product_id and cr.status <> 'CANCELLED') as customers_requested
    from public.purchase_batches b
    join public.products p on p.id = b.product_id
    join public.suppliers s on s.id = b.supplier_id
    where (p_product_id is null or b.product_id = p_product_id)
      and (p_supplier_id is null or b.supplier_id = p_supplier_id)
      and (not p_only_pending_cost or b.cost_status = 'PENDING')
    order by b.received_date desc, b.created_at desc
    limit greatest(coalesce(p_limit, 200), 1)) t;

  return jsonb_build_object('items', v_items,
    'pending_cost_count', (select count(*) from public.purchase_batches where cost_status = 'PENDING'));
end $$;

create or replace function public.rpc_list_restocks(
  p_only_pending_cost boolean default false,
  p_limit int default 200
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.received_date desc), '[]'::jsonb) into v_items
  from (
    select r.id, r.restock_number, r.received_date, r.expiry_date, r.quantity,
           r.unit_cost, r.cost_pending, r.cost_flagged, r.previous_unit_cost,
           r.supplier_invoice, r.notes, r.batch_id, r.status,
           p.name as product_name, p.product_code, s.name as supplier_name,
           u.full_name as received_by_name,
           case when r.cost_flagged and r.unit_cost is not null and r.previous_unit_cost is not null
                then format('Purchase cost changed from %s to %s. Selling price was NOT changed.',
                            to_char(r.previous_unit_cost, 'FM999,990.00'),
                            to_char(r.unit_cost, 'FM999,990.00')) end as cost_change_warning
    from public.restocks r
    join public.products p on p.id = r.product_id
    join public.suppliers s on s.id = r.supplier_id
    left join public.app_users u on u.id = r.received_by
    where (not p_only_pending_cost or r.cost_pending)
    order by r.received_date desc, r.created_at desc
    limit greatest(coalesce(p_limit, 200), 1)) t;

  return jsonb_build_object('items', v_items);
end $$;

