-- ----------------------------------------------------------------------------
-- >>> 0019_rpcs_sale_detail.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0019 — Sale detail & own-sales (role-aware payloads)
-- ============================================================================
-- Appended rather than folded into 0016 because migrations are append-only once
-- they have been applied.
--
-- rpc_sale_detail is the clearest expression of the cost-visibility rule: it
-- returns cogs_amount, gross_profit and per-line costs ONLY when the caller is
-- the owner. A staff member receives their own sale with those keys set to null
-- — the field is absent from the data, not merely hidden in the UI, so a staff
-- token cannot read cost even by calling this function directly.
-- ============================================================================

create or replace function public.rpc_sale_detail(p_sale_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_is_owner boolean := public.fn_is_owner();
  v_sale     public.sales;
  v_items    jsonb;
  v_returns  jsonb;
  v_comm     jsonb;
begin
  perform public.fn_require_internal();

  select * into v_sale from public.sales where id = p_sale_id;
  if not found then
    raise exception 'SALE_NOT_FOUND: no sale with id %', p_sale_id using errcode = '23503';
  end if;

  -- Staff may open only their own sales; the owner may open any.
  if not v_is_owner and v_sale.staff_id <> auth.uid() then
    raise exception 'NOT_YOUR_SALE: this sale belongs to another staff member' using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.product_name), '[]'::jsonb) into v_items
  from (
    select si.id, si.product_id, p.name as product_name, p.product_code,
           si.quantity, si.unit_price, si.line_subtotal, si.line_discount, si.line_total,
           si.returned_qty, si.refunded_amount,
           -- cost fields are present for the owner and null for everyone else
           case when v_is_owner then si.unit_cogs end as unit_cogs,
           case when v_is_owner then si.line_cogs end as line_cogs
    from public.sale_items si
    join public.products p on p.id = si.product_id
    where si.sale_id = p_sale_id) t;

  if v_is_owner then
    select coalesce(jsonb_agg(to_jsonb(t) order by t.return_date desc), '[]'::jsonb) into v_returns
    from (
      select r.id, r.return_number, r.return_date, r.return_type, r.return_amount,
             r.cogs_reversed, r.restock_decision, r.reason, r.processed_by
      from public.returns r where r.sale_id = p_sale_id) t;
  else
    v_returns := '[]'::jsonb;
  end if;

  -- Commission rows for this sale belong to the seller, so a staff member may
  -- see their own; the owner sees all.
  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at), '[]'::jsonb) into v_comm
  from (
    select c.id, c.type, c.amount, c.rate, c.sale_date, c.staff_id, c.created_at
    from public.commissions c
    where c.sale_id = p_sale_id
      and (v_is_owner or c.staff_id = auth.uid())) t;

  return jsonb_build_object(
    'sale', jsonb_build_object(
      'id', v_sale.id, 'sale_number', v_sale.sale_number, 'sale_date', v_sale.sale_date,
      'created_at', v_sale.created_at, 'subtotal', v_sale.subtotal,
      'discount_amount', v_sale.discount_amount, 'discount_percent', v_sale.discount_percent,
      'total_amount', v_sale.total_amount, 'returned_amount', v_sale.returned_amount,
      'payment_method', v_sale.payment_method, 'status', v_sale.status,
      'staff_id', v_sale.staff_id,
      'staff_name', (select full_name from public.app_users where id = v_sale.staff_id),
      'cogs_amount', case when v_is_owner then v_sale.cogs_amount end,
      'gross_profit', case when v_is_owner then v_sale.gross_profit end,
      'void_reason', v_sale.void_reason, 'voided_at', v_sale.voided_at,
      'can_return', v_is_owner and v_sale.status <> 'VOIDED'
    ),
    'items', v_items,
    'returns', v_returns,
    'commissions', v_comm,
    'cost_visible', v_is_owner,
    'note', case when v_is_owner then null
                 else 'Purchase cost and profit are not shown for staff accounts.' end
  );
end $$;

-- Own sales history for the staff "My Sales" page. No cost fields at all.
create or replace function public.rpc_my_sales(
  p_limit int default 50,
  p_from  date default null,
  p_to    date default null
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid   uuid := auth.uid();
  v_items jsonb;
  v_totals record;
  v_month_start date := date_trunc('month', current_date)::date;
begin
  perform public.fn_require_internal();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb) into v_items
  from (
    select sa.id, sa.sale_number, sa.sale_date, sa.created_at,
           sa.subtotal, sa.discount_amount, sa.total_amount, sa.returned_amount,
           public.fn_money(sa.total_amount - sa.returned_amount) as net_amount,
           sa.payment_method, sa.status,
           (select count(*) from public.sale_items si where si.sale_id = sa.id) as line_count
    from public.sales sa
    where sa.staff_id = v_uid
      and (p_from is null or sa.sale_date >= p_from)
      and (p_to   is null or sa.sale_date <= p_to)
    order by sa.created_at desc
    limit greatest(coalesce(p_limit, 50), 1)) t;

  select
    count(*) as sale_count,
    public.fn_money(coalesce(sum(total_amount - returned_amount), 0)) as net_sales,
    public.fn_money(coalesce(sum(discount_amount), 0)) as discounts
    into v_totals
  from public.sales
  where staff_id = v_uid and status <> 'VOIDED'
    and sale_date >= v_month_start
    and (p_from is null or sale_date >= p_from)
    and (p_to   is null or sale_date <= p_to);

  return jsonb_build_object(
    'items', v_items,
    'month_totals', jsonb_build_object(
      'sale_count', v_totals.sale_count,
      'net_sales', v_totals.net_sales,
      'discounts', v_totals.discounts,
      'commission', (select public.fn_money(coalesce(sum(amount), 0)) from public.commissions
                      where staff_id = v_uid and sale_date >= v_month_start)
    )
  );
end $$;

-- My commission ledger, with the EARNED / reversal split the spec calls for.
create or replace function public.rpc_my_commission(
  p_from date default null,
  p_to   date default null
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid      uuid := auth.uid();
  v_items    jsonb;
  v_totals   jsonb;
  v_payments jsonb;
  v_paid     numeric;
begin
  perform public.fn_require_internal();

  -- The full ledger, including reversal rows, so a staff member can see exactly
  -- why their commission changed (§36: original records are never deleted).
  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb) into v_items
  from (
    select c.id, c.sale_date, c.type, c.amount, c.rate, c.note, c.created_at,
           sa.sale_number, sa.total_amount as sale_total, sa.discount_amount as sale_discount,
           r.return_number
    from public.commissions c
    left join public.sales sa on sa.id = c.sale_id
    left join public.returns r on r.id = c.return_id
    where c.staff_id = v_uid
      and (p_from is null or c.sale_date >= p_from)
      and (p_to   is null or c.sale_date <= p_to)) t;

  select jsonb_build_object(
           'earned',   public.fn_money(coalesce(sum(amount) filter (where type = 'EARNED'), 0)),
           'reversed', public.fn_money(coalesce(sum(amount) filter (where type in ('RETURN_REVERSAL','VOID_REVERSAL')), 0)),
           'net',      public.fn_money(coalesce(sum(amount), 0)))
    into v_totals
  from public.commissions where staff_id = v_uid;

  select public.fn_money(coalesce(sum(amount), 0)),
         coalesce(jsonb_agg(jsonb_build_object(
           'payment_number', payment_number, 'amount', amount, 'payment_date', payment_date,
           'reference', reference, 'period_start', period_start, 'period_end', period_end)
           order by payment_date desc), '[]'::jsonb)
    into v_paid, v_payments
  from public.commission_payments where staff_id = v_uid;

  return jsonb_build_object(
    'items', v_items,
    'totals', v_totals,
    'payments', jsonb_build_object('paid', v_paid, 'entries', v_payments),
    'outstanding', public.fn_money((v_totals ->> 'net')::numeric - v_paid)
  );
end $$;

-- ----------------------------------------------------------------------------
-- >>> 0020_rpcs_extras.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0020 — Remaining read RPCs
-- ============================================================================
-- Supplier payment history and the staff-performance report. Kept in their own
-- migration (appended, never folded into an applied one) and numbered below
-- 9999 so the API-surface grants still run last.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Supplier payments (owner). NOT an expense — this is a balance-sheet
-- settlement, so it has its own report and never appears in the P&L (§24).
-- ---------------------------------------------------------------------------
create or replace function public.rpc_report_supplier_payments(
  p_supplier_id uuid default null,
  p_from date default null,
  p_to   date default null
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
  v_total numeric;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.payment_date desc), '[]'::jsonb) into v_items
  from (
    select sp.id, sp.payment_number, sp.supplier_id, s.name as supplier_name,
           sp.amount, sp.payment_method, sp.payment_date, sp.reference, sp.notes,
           sp.created_at, sp.voided_at,
           (select count(*) from public.supplier_payment_allocations a where a.payment_id = sp.id) as lines_settled
    from public.supplier_payments sp
    join public.suppliers s on s.id = sp.supplier_id
    where (p_supplier_id is null or sp.supplier_id = p_supplier_id)
      and (p_from is null or sp.payment_date >= p_from)
      and (p_to   is null or sp.payment_date <= p_to)
    order by sp.payment_date desc, sp.created_at desc) t;

  select public.fn_money(coalesce(sum(amount), 0)) into v_total
  from public.supplier_payments
  where voided_at is null
    and (p_supplier_id is null or supplier_id = p_supplier_id)
    and (p_from is null or payment_date >= p_from)
    and (p_to   is null or payment_date <= p_to);

  return jsonb_build_object(
    'items', v_items,
    'total', v_total,
    'note', 'Supplier payments settle stock already recognised in COGS at the time of sale. They are not operating expenses and are excluded from net profit.'
  );
end $$;

-- ---------------------------------------------------------------------------
-- Staff performance (owner, §55): sales, discounts and commission per person,
-- paired with what they were paid. Deliberately excludes cost and profit — the
-- owner sees those in the P&L, not attributed per staff member here.
-- ---------------------------------------------------------------------------
create or replace function public.rpc_report_staff_performance(
  p_from date default date_trunc('month', current_date)::date,
  p_to   date default current_date
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.net_sales desc), '[]'::jsonb) into v_items
  from (
    select u.id as staff_id, u.full_name, u.role, u.commission_rate, u.active,
           count(sa.id) as sale_count,
           public.fn_money(coalesce(sum(sa.subtotal), 0)) as gross_sales,
           public.fn_money(coalesce(sum(sa.discount_amount), 0)) as discounts_given,
           public.fn_money(coalesce(sum(sa.returned_amount), 0)) as returns,
           public.fn_money(coalesce(sum(sa.total_amount - sa.returned_amount), 0)) as net_sales,
           public.fn_money(coalesce(sum(sa.total_amount - sa.returned_amount)
                                    / nullif(count(sa.id), 0), 0)) as average_sale,
           public.fn_money(coalesce((select sum(c.amount) from public.commissions c
              where c.staff_id = u.id and c.sale_date between p_from and p_to), 0)) as commission
    from public.app_users u
    left join public.sales sa
      on sa.staff_id = u.id and sa.sale_date between p_from and p_to and sa.status <> 'VOIDED'
    where u.role in ('STAFF','OWNER')
    group by u.id, u.full_name, u.role, u.commission_rate, u.active) t;

  return jsonb_build_object('from', p_from, 'to', p_to, 'staff', v_items);
end $$;

-- ---------------------------------------------------------------------------
-- Daily sales series. Used by the owner dashboard and the Reports page so the
-- chart and the table read the same aggregation.
-- ---------------------------------------------------------------------------
create or replace function public.rpc_report_daily_sales(
  p_from date default (current_date - 29),
  p_to   date default current_date
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.sale_date), '[]'::jsonb) into v_items
  from (
    select d::date as sale_date,
           count(sa.id) as sale_count,
           public.fn_money(coalesce(sum(sa.total_amount - sa.returned_amount), 0)) as net_sales,
           public.fn_money(coalesce(sum(sa.discount_amount), 0)) as discounts,
           public.fn_money(coalesce(sum(sa.cogs_amount), 0)) as cogs,
           public.fn_money(coalesce(sum(sa.total_amount - sa.returned_amount - sa.cogs_amount), 0)) as gross_profit
    from generate_series(p_from, p_to, interval '1 day') d
    left join public.sales sa on sa.sale_date = d::date and sa.status <> 'VOIDED'
    group by d) t;

  return jsonb_build_object('from', p_from, 'to', p_to, 'items', v_items);
end $$;

-- ----------------------------------------------------------------------------
-- >>> 0021_rpcs_statements_requests.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0021 — Statement listing + demand drill-down
-- ============================================================================
-- Two read RPCs the Owner screens need:
--   rpc_list_supplier_statements — generated statements, newest month first.
--     `supplier_statements` is an owner-only table and is deliberately NOT
--     granted to `authenticated`, so the Owner UI cannot read it directly; it
--     comes through this definer function exactly like the other owner data.
--   rpc_request_detail — one customer request with its full history.
--
-- Numbered below 9999 so the API-surface grants still run last. New functions
-- inherit EXECUTE for PUBLIC at creation, which 9999 then closes; the
-- anon-surface assertion in 03_security_rls.sql is the tripwire if that order
-- is ever broken.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Supplier statements (owner). Recomputed totals only — nothing typed in.
-- ---------------------------------------------------------------------------
create or replace function public.rpc_list_supplier_statements(
  p_supplier_id uuid default null,
  p_limit       int  default 100
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.period_month desc), '[]'::jsonb) into v_items
  from (
    select st.id, st.statement_number, st.period_month, st.opening_outstanding,
           st.units_sold, st.total_payable, st.total_paid, st.outstanding,
           st.generated_at,
           s.name as supplier_name, s.supplier_code, s.contact_name, s.phone, s.email,
           u.full_name as generated_by_name
    from public.supplier_statements st
    join public.suppliers s on s.id = st.supplier_id
    left join public.app_users u on u.id = st.generated_by
    where (p_supplier_id is null or st.supplier_id = p_supplier_id)
    order by st.period_month desc
    limit greatest(coalesce(p_limit, 100), 1)) t;

  return jsonb_build_object('items', v_items);
end $$;

-- ---------------------------------------------------------------------------
-- Internal supplier notes (owner). `supplier_internal_notes` holds notes that
-- are for the owner's eyes only and carries no grant, so it is read through
-- this definer wrapper for the same reason statements are.
-- ---------------------------------------------------------------------------
create or replace function public.rpc_list_supplier_notes(
  p_supplier_id uuid,
  p_limit       int default 50
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb) into v_items
  from (
    select n.id, n.supplier_id, n.note, n.created_at,
           u.full_name as created_by_name
    from public.supplier_internal_notes n
    left join public.app_users u on u.id = n.created_by
    where n.supplier_id = p_supplier_id
    order by n.created_at desc
    limit greatest(coalesce(p_limit, 50), 1)) t;

  return jsonb_build_object('items', v_items);
end $$;

-- ---------------------------------------------------------------------------
-- One customer request in full (owner / staff). Used by the Requests screen
-- when a card is opened, so the phone number is only fetched on demand and
-- only for an internal caller.
-- ---------------------------------------------------------------------------
create or replace function public.rpc_request_detail(
  p_request_id uuid
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_row jsonb;
begin
  perform public.fn_require_internal();

  select to_jsonb(t) into v_row
  from (
    select cr.id, cr.request_number, cr.customer_name, cr.customer_phone,
           cr.requested_product_name, cr.quantity, cr.message, cr.photo_url,
           cr.source, cr.status, cr.was_unavailable, cr.owner_note,
           cr.status_history, cr.created_at, cr.updated_at,
           cr.product_id, p.name as product_name, p.product_code,
           p.selling_price as product_price, c.name as category_name,
           public.fn_availability(
             public.fn_staff_on_hand(p.id), p.minimum_stock) as availability,
           public.fn_staff_on_hand(p.id) as quantity_on_hand,
           u.full_name as handled_by_name,
           (select count(*) from public.customer_requests x
             where x.requested_product_name = cr.requested_product_name) as same_product_requests,
           (select count(*) from public.customer_requests x
             where cr.customer_phone is not null
               and x.customer_phone = cr.customer_phone) as same_customer_requests
    from public.customer_requests cr
    left join public.products p   on p.id = cr.product_id
    left join public.categories c on c.id = cr.category_id
    left join public.app_users u  on u.id = cr.handled_by
    where cr.id = p_request_id) t;

  if v_row is null then
    raise exception 'REQUEST_NOT_FOUND: no customer request with that id' using errcode = 'P0001';
  end if;

  return v_row;
end $$;

-- ----------------------------------------------------------------------------
-- >>> 0022_rpcs_row_ids.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0022 — Row identities for owner actions
-- ============================================================================
-- Two read RPCs were returning everything the owner needs to *see* but not the
-- primary key they need to *act*. Without the id the UI would have to look the
-- row up again from a second source, which is exactly the kind of drift the
-- derived-data rule is meant to prevent, so the ids are returned instead.
--
--   rpc_report_expenses  → adds e.id            (void an expense)
--   rpc_report_inventory → adds p.id            (adjust stock from the report)
--
-- Numbered below 9999 so the API-surface grants still run last.
-- ============================================================================

create or replace function public.rpc_report_expenses(
  p_from date default date_trunc('month', current_date)::date,
  p_to   date default current_date
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
  v_by_category jsonb;
  v_total numeric;
begin
  perform public.fn_require_owner();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.expense_date desc), '[]'::jsonb) into v_items from (
    select e.id, e.expense_number, e.expense_date, e.category, e.amount, e.payment_method,
           e.description, e.receipt_url, u.full_name as created_by_name
    from public.expenses e left join public.app_users u on u.id = e.created_by
    where e.expense_date between p_from and p_to
    order by e.expense_date desc) t;

  select coalesce(jsonb_agg(to_jsonb(c) order by c.total desc), '[]'::jsonb) into v_by_category from (
    select category, public.fn_money(sum(amount)) as total, count(*) as entries
    from public.expenses where expense_date between p_from and p_to
    group by category) c;

  select public.fn_money(coalesce(sum(amount), 0)) into v_total
  from public.expenses where expense_date between p_from and p_to;

  return jsonb_build_object('from', p_from, 'to', p_to, 'items', v_items,
                            'by_category', v_by_category, 'total', v_total);
end $$;

create or replace function public.rpc_report_inventory(
  p_category_id uuid default null, p_only_attention boolean default false
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
  v_totals record;
begin
  perform public.fn_require_owner();

  -- Identical to the original except for v.product_id, which the owner needs in
  -- order to adjust stock straight from this report.
  select coalesce(jsonb_agg(to_jsonb(t) order by t.stock_value desc, t.name), '[]'::jsonb) into v_items
  from (
    select v.product_id, v.product_code, v.name, v.category_name, v.supplier_name, v.quantity_on_hand,
           v.avg_unit_cost, v.stock_value, v.selling_price, v.unit_margin, v.availability,
           v.expiry_status, v.expiry_date, v.minimum_stock
    from public.v_owner_inventory v
    where (p_category_id is null or v.category_name = (select name from public.categories where id = p_category_id))
      and (not p_only_attention or v.availability <> 'AVAILABLE' or v.expiry_status in ('EXPIRED','EXPIRING_SOON'))
  ) t;

  select public.fn_money(sum(stock_value)) as total_value,
         sum(quantity_on_hand) as total_units,
         count(*) as sku_count,
         public.fn_money(sum(quantity_on_hand * selling_price)) as retail_value
    into v_totals from public.v_owner_inventory;

  return jsonb_build_object('items', v_items, 'totals', to_jsonb(v_totals));
end $$;

-- ----------------------------------------------------------------------------
-- >>> 0023_rpcs_request_ids.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0023 — Request identity in the request report
-- ============================================================================
-- The customer-request report listed everything an owner reads but omitted the
-- request's id, so the Requests screen could not act on a row without a second
-- lookup. The id is added (aliased to `id`, alongside the existing camelCase
-- keys the UI already consumes) and nothing else changes.
--
-- Numbered below 9999 so the API-surface grants still run last.
-- ============================================================================

create or replace function public.rpc_report_customer_requests(
  p_from date default (current_date - 30),
  p_to   date default current_date,
  p_status public.request_status default null,
  p_source public.request_source default null,
  p_product_id uuid default null
) returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_items jsonb;
  v_stats record;
begin
  perform public.fn_require_internal();

  select coalesce(jsonb_agg(to_jsonb(t) order by t.created_at desc), '[]'::jsonb) into v_items from (
    select cr.id, cr.request_number as "requestNumber", cr.customer_name as "customerName",
           cr.customer_phone as "customerPhone", cr.requested_product_name as "product",
           cr.quantity, cr.status, cr.source, cr.was_unavailable, cr.created_at, cr.updated_at,
           p.name as matched_product, cr.owner_note, cr.message
    from public.customer_requests cr
    left join public.products p on p.id = cr.product_id
    where cr.created_at::date between p_from and p_to
      and (p_status is null or cr.status = p_status)
      and (p_source is null or cr.source = p_source)
      and (p_product_id is null or cr.product_id = p_product_id)
    order by cr.created_at desc limit 500) t;

  select count(*) as total,
         count(*) filter (where status = 'NEW') as new_count,
         count(*) filter (where status in ('FULFILLED')) as fulfilled,
         count(distinct customer_phone) as customers,
         count(*) filter (where was_unavailable) as unavailable
    into v_stats from public.customer_requests
   where created_at::date between p_from and p_to;

  return jsonb_build_object('from', p_from, 'to', p_to, 'items', v_items, 'stats', to_jsonb(v_stats));
end $$;

-- ----------------------------------------------------------------------------
-- >>> 0024_rpc_supplier_contact.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 0024 — A supplier keeps their own contact details
-- ============================================================================
-- The supplier portal lets a supplier keep their contact information current so
-- the shop can actually reach them. Before this, the only way was for the owner
-- to edit it, which is a silly thing to require for a phone number.
--
-- The safety of this function is in what it does NOT touch. A supplier can
-- change four contact fields on their own row and nothing else:
--   • the row is chosen by fn_current_supplier_id(), derived from the caller's
--     own link — a supplier cannot name a different supplier id;
--   • `name`, `supplier_code`, `tin_number`, `payment_terms` and `active` are
--     commercial record and remain owner-only;
--   • no financial figure is writable from a supplier session anywhere, and the
--     change is written to the audit log.
--
-- Numbered below 9999 so the API-surface grants still run last.
-- ============================================================================

create or replace function public.rpc_update_supplier_contact(
  p_contact_name text default null,
  p_phone        text default null,
  p_email        text default null,
  p_address      text default null,
  p_notes        text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_supplier_id uuid := public.fn_current_supplier_id();
  v_before jsonb;
  v_user public.app_users;
begin
  if v_supplier_id is null then
    -- fn_require_internal() lets the owner correct a supplier's details too,
    -- which is useful when a supplier phones in with a new number.
    if public.fn_is_owner() then
      raise exception 'SUPPLIER_REQUIRED: say which supplier to update by signing in as that supplier'
        using errcode = '42501';
    end if;
    perform public.fn_require_internal();
    raise exception 'NOT_A_SUPPLIER: this account is not linked to a supplier'
      using errcode = '42501';
  end if;

  select to_jsonb(s) into v_before
  from (
    select contact_name, phone, email, address
    from public.suppliers where id = v_supplier_id
  ) s;

  update public.suppliers
     set contact_name = coalesce(p_contact_name, contact_name),
         phone        = coalesce(p_phone, phone),
         email        = coalesce(p_email, email),
         address      = coalesce(p_address, address)
   where id = v_supplier_id;

  v_user := public.fn_current_user_row();

  perform public.fn_audit('SUPPLIER_CONTACT_UPDATE', 'suppliers', v_supplier_id, v_before,
    jsonb_build_object(
      'contact_name', p_contact_name, 'phone', p_phone,
      'email', p_email, 'address', p_address, 'notes', p_notes,
      'by', coalesce(v_user.full_name, 'supplier portal')));

  -- The note is stored as an internal note so the owner sees it alongside the
  -- supplier's record without it becoming part of the commercial data.
  if p_notes is not null and length(trim(p_notes)) > 0 then
    insert into public.supplier_internal_notes (supplier_id, note, created_by)
    values (v_supplier_id, 'Supplier note: ' || trim(p_notes), v_user.id);
  end if;

  return jsonb_build_object('supplier_id', v_supplier_id, 'updated', true);
end $$;

-- ----------------------------------------------------------------------------
-- >>> 9999_api_grants.sql
-- ----------------------------------------------------------------------------
-- ============================================================================
-- LuBella  |  Migration 9999 — API surface grants  (single source of truth)
-- ============================================================================
-- WHY THIS FILE IS NUMBERED 9999 AND MUST STAY THE LAST MIGRATION:
--   Every migration after the one that revokes privileges would otherwise
--   re-introduce the exposure, because CREATE FUNCTION grants EXECUTE to PUBLIC
--   by default. Migration 0019 proved this in practice: its two new functions
--   were briefly callable by `anon` until this file ran again.
--   If a future migration adds functions, it must be numbered below 9999, and
--   the security test asserting the anonymous surface honours this list is the
--   tripwire that catches any drift.
--
-- Why this file exists separately and runs last:
--   CREATE FUNCTION grants EXECUTE to PUBLIC by default, and that default is
--   re-applied to every function created AFTER the blanket revoke in 0010.
--   So the revoke has to happen again once all functions exist, and only then
--   is the intended surface opened. Every EXECUTE grant in the project lives
--   here, so there is exactly one list to audit.
--
-- The grants are generated from the catalog rather than typed out, which means
-- a signature change can never silently leave a function ungranted (or, worse,
-- granted to the wrong audience).
-- ============================================================================

-- Step 1: close everything again — including the helper grants from 0010 and
-- anything inherited by functions created in 0011-0017.
revoke all on all functions in schema public from public, anon, authenticated;

-- Step 2: helpers that must be executable by the caller, because RLS policy
-- expressions and definer views are evaluated with the caller's privileges.
-- Each of these reveals only information the caller already owns (their own
-- role, their own supplier id, or a pure formatting/maths helper).
grant execute on function public.fn_is_owner()            to anon, authenticated;
grant execute on function public.fn_is_staff()            to anon, authenticated;
grant execute on function public.fn_is_internal()         to anon, authenticated;
grant execute on function public.fn_is_supplier()         to anon, authenticated;
grant execute on function public.fn_current_supplier_id() to anon, authenticated;
grant execute on function public.fn_current_user_row()    to authenticated;
grant execute on function public.fn_money(numeric)        to anon, authenticated;
grant execute on function public.fn_availability(int, int) to anon, authenticated;
grant execute on function public.fn_expiry_status(date, int) to anon, authenticated;
grant execute on function public.fn_urlencode(text)       to anon, authenticated;
grant execute on function public.fn_public_settings()     to anon, authenticated;
-- Audience-guarded wrappers used by the views. Each returns only what its
-- audience is entitled to; the raw primitives (fn_on_hand, fn_avg_unit_cost,
-- fn_setting) are deliberately NOT granted to anyone.
grant execute on function public.fn_public_setting(text, jsonb)  to anon, authenticated;
grant execute on function public.fn_public_availability(uuid, int) to anon, authenticated;
grant execute on function public.fn_staff_on_hand(uuid)          to authenticated;
grant execute on function public.fn_contact_links(text)   to anon, authenticated;
grant execute on function public.fn_build_order_message(jsonb, numeric, text, text, text) to anon, authenticated;

-- Step 3: the RPC API. Public = safe for anonymous customers; everything else is
-- granted to `authenticated` only, and each of those functions re-checks the
-- caller's role internally (fn_require_owner / fn_require_internal), so a staff
-- or supplier token calling an owner RPC is rejected inside the database.
do $$
declare
  f record;
  v_public_api text[] := array[
    'rpc_public_catalog',
    'rpc_public_filters',
    'rpc_build_order_message',
    'rpc_submit_customer_request'
  ];
begin
  for f in
    select p.oid::regprocedure as signature, p.proname
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname like 'rpc\_%'
    order by p.proname
  loop
    if f.proname = any (v_public_api) then
      execute format('grant execute on function %s to anon, authenticated', f.signature);
    else
      execute format('grant execute on function %s to authenticated', f.signature);
    end if;
  end loop;
end $$;

-- Step 4: sequences. Only the definer functions touch them.
do $$
declare r record;
begin
  for r in select sequence_name from information_schema.sequences where sequence_schema = 'public'
  loop
    execute format('revoke all on sequence public.%I from anon, authenticated', r.sequence_name);
  end loop;
end $$;

-- -- Verification helper (owner-only) -----------------------------------------
-- Lists the API surface actually reachable by each client role, so the grant
-- list can be inspected from the Audit area rather than assumed.
create or replace function public.rpc_api_surface()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select case when public.fn_is_owner() then jsonb_build_object(
    'anon', coalesce((select jsonb_agg(p.proname order by p.proname)
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'public' and has_function_privilege('anon', p.oid, 'EXECUTE')), '[]'::jsonb),
    'authenticated', coalesce((select jsonb_agg(p.proname order by p.proname)
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
      where n.nspname = 'public' and has_function_privilege('authenticated', p.oid, 'EXECUTE')), '[]'::jsonb)
  ) else '{}'::jsonb end;
$$;

revoke all on function public.rpc_api_surface() from public, anon, authenticated;
grant execute on function public.rpc_api_surface() to authenticated;
